const ARTICLES=[{"n": 1, "title": "OBJETO DA LEI", "legal": "Caput Art. 1º Esta Lei dispõe sobre a estruturação do Plano de Cargos e Carreiras e a parte organizacional da Guarda Civil Municipal, a criação de cargos efetivos e de funções gratificadas, o estabelecimento de jornada de trabalho, a instituição de tabela de vencimentos e outros temas afetos.", "comment": "Delimita o alcance da LC 198/2025. A norma não trata apenas de remuneração: alcança organização da GCM, cargos, funções gratificadas, jornada, vencimentos e temas funcionais correlatos.", "memorize": "Objeto amplo: carreira + organização + cargos/funções + jornada + vencimentos.", "trap": "", "juris": ""}, {"n": 2, "title": "CONCEITOS FUNDAMENTAIS", "legal": "Caput Art. 2º Para efeitos desta Lei, consideram-se conceitos fundamentais: I Cargo: conjunto de competências e responsabilidades atribuídas ao Guarda Civil Municipal, com atividades semelhantes quanto a natureza da atuação; II Função: conjunto de tarefas correlatas à cada categoria que diferem conforme as competências das classes; III Carreira: agrupamento de classes e níveis que organizam e hierarquizam as atividades, definem a evolução funcional e a remuneração do Guarda Civil Municipal; IV Classe: conjunto de atividades semelhantes quanto à natureza e diferentes quanto ao grau de responsabilidade e complexidade das funções, escalonadas de acordo com a hierarquia na carreira, guardando correlação entre si; V Nível: posicionamento dentro das classes; VI Progressão: evolução funcional do Guarda Civil Municipal de uma referência para outra, dentro do mesmo nível, observado o tempo de serviço e a avaliação de mérito; VII Promoção: evolução funcional do Guarda Civil Municipal de um nível para outro imediatamente superior, segundo critérios objetivos e requisitos previstos nesta Lei; VIII Adicional de Periculosidade: direito do trabalhador que exerce atividades que apresentam risco à vida ou risco iminente de acidentes graves; IX Vencimento Base: vencimento correspondente a um nível e referência no qual o Guarda Civil Municipal está enquadrado, sob o qual irão incidir todas as demais vantagens.", "comment": "É o glossário da lei. As definições deste artigo orientam a interpretação dos capítulos seguintes e são especialmente importantes para diferenciar classe, nível, promoção e progressão.", "memorize": "Promoção = vertical; progressão = horizontal.", "trap": "Não troque progressão por promoção. A própria lei define os dois institutos separadamente.", "juris": ""}, {"n": 3, "title": "ESTRUTURA ADMINISTRATIVA", "legal": "Caput Art. 3º A Guarda Civil Municipal, no plano de sua estrutura orgânica e orçamentária, integra a Secretaria Municipal de Governo e a Superintendência de Segurança Pública e Defesa Social e possui a seguinte estrutura administrativa: I Comando; II Corregedoria; III Ouvidoria; IV Inspetoria.", "comment": "Define a vinculação administrativa da GCM e seus quatro núcleos: Comando, Corregedoria, Ouvidoria e Inspetoria.", "memorize": "4 núcleos: Comando, Corregedoria, Ouvidoria, Inspetoria.", "trap": "", "juris": ""}, {"n": 4, "title": "SUPERIORES HIERÁRQUICOS", "legal": "Caput Art. 4º São superiores hierárquicos ao Comando da Guarda Civil Municipal: I o Prefeito Municipal; II o Superintendente de Segurança Pública e Defesa Social.", "comment": "Acima do Comando, a própria lei reconhece dois superiores hierárquicos: Prefeito e Superintendente de Segurança Pública e Defesa Social.", "memorize": "Superiores ao Comando: Prefeito + Superintendente.", "trap": "", "juris": ""}, {"n": 5, "title": "COMANDO DA GCM", "legal": "Caput Art. 5º O Comando da Guarda Civil Municipal é o órgão responsável pela direção, coordenação, desenvolvimento, implantação e supervisão de todas as atividades operacionais e administrativas da Corporação. Parágrafo único Compete ao Comando da Guarda Civil Municipal: I planejamento, organização e direção das ações da Guarda Civil Municipal; II representação da Instituição perante autoridades, órgãos e entidades; III expedição de atos normativos internos para o bom funcionamento da Corporação; IV zelo pela disciplina, hierarquia e cumprimento das leis, regulamentos e ordens de serviço; V apresentação de planos e programas de segurança pública ao Chefe do Poder Executivo Municipal.", "comment": "Concentra no Comando a direção administrativa e operacional, além de planejamento, representação institucional, disciplina e apresentação de planos ao Executivo.", "memorize": "Comando = direção e planejamento.", "trap": "", "juris": ""}, {"n": 6, "title": "SUBCOMANDO", "legal": "Caput Art. 6º O Subcomando da Guarda Civil Municipal, integrante da estrutura do Comando, tem por atribuição auxiliar o Comando da Guarda Civil Municipal no desempenho de suas competências e substituí-lo nos casos de ausência, afastamento ou impedimento, assumindo, nesse período, a chefia plena da Instituição. Parágrafo único Compete ao Subcomando da Guarda Civil Municipal: I coordenação das ações operacionais e administrativas sob delegação do Comandante; II supervisão do cumprimento das ordens e diretrizes estabelecidas; III assessoria ao Comando na tomada de decisões estratégicas; IV desempenho de outras atribuições que lhe sejam conferidas pelo Comando.", "comment": "O Subcomando é órgão de auxílio e substituição. Na ausência, afastamento ou impedimento do Comando, assume a chefia plena da instituição durante o período.", "memorize": "Subcomando = auxilia e substitui.", "trap": "", "juris": ""}, {"n": 7, "title": "CONTROLE INTERNO E EXTERNO", "legal": "Caput Art. 7º O funcionamento da Guarda Civil Municipal será acompanhado por órgãos próprios, permanentes, autônomos e com atribuições de fiscalização, investigação e auditoria, mediante: I controle interno, exercido pela Corregedoria da Guarda Civil Municipal, para apurar as infrações disciplinares atribuídas aos integrantes de seu quadro; e II controle externo, exercido pela Ouvidoria da Guarda Civil Municipal, com atuação independente em relação ao Comando da Guarda, com a função de receber, examinar e encaminhar reclamações, sugestões, elogios e denúncias acerca da conduta de dirigentes e integrantes e das atividades do órgão, propor soluções, oferecer recomendações e informar os resultados aos interessados, garantindo-lhes orientação, informação e resposta.", "comment": "Cria uma distinção central: Corregedoria exerce controle interno disciplinar; Ouvidoria exerce controle externo institucional e recebe manifestações da sociedade.", "memorize": "Corregedoria = interno; Ouvidoria = externo.", "trap": "Corregedoria não é Ouvidoria: o examinador pode inverter controle interno e externo.", "juris": ""}, {"n": 8, "title": "CORREGEDORIA", "legal": "Caput Art. 8º A Corregedoria da Guarda Civil Municipal é órgão autônomo, de controle interno, com o objetivo de apuração da responsabilidade dos serviços públicos integrantes de sua estrutura administrativa, mediante abertura de inquéritos e sindicâncias e instauração de processos administrativos pertinentes. Parágrafo único Compete à Corregedoria da Guarda Civil Municipal: I instauração e condução de sindicâncias e processos administrativos disciplinares; II fiscalização da conduta funcional dos integrantes da Guarda Civil Municipal; III proposição de medidas de correção e aprimoramento de procedimentos; IV manutenção de registros atualizados de processos e penalidades aplicadas; DISPOSITIVO TEXTO LEGAL V realização de visitas de inspeção e correições em qualquer unidade da Guarda Civil Municipal e/ou local em que esta atue.", "comment": "A Corregedoria atua na apuração de responsabilidade funcional, com sindicâncias, PADs, inspeções, correições e registros de penalidades.", "memorize": "Corregedoria = sindicância/PAD/correição.", "trap": "", "juris": ""}, {"n": 9, "title": "OUVIDORIA", "legal": "Caput Art. 9º A Ouvidoria da Guarda Civil Municipal é o órgão de participação e controle externo, incumbido de receber, examinar e encaminhar reclamações, sugestões, elogios e denúncias acerca da conduta de seus dirigentes e integrantes e das atividades do órgão, propor soluções, oferecer recomendações e informar os resultados aos interessados, garantindo-lhes orientação, informação e resposta. § 1º Compete à Ouvidoria da Guarda Civil Municipal: I promoção da transparência e diálogo entre a comunidade e a GCM; II direcionamento de manifestações aos setores competentes e acompanhamento da solução; III elaboração de relatórios periódicos sobre as demandas recebidas; IV atuação com independência e imparcialidade, preservando o sigilo das informações quando necessário. § 2º Até a implementação da Ouvidoria própria da Guarda Civil Municipal, as funções de Ouvidoria da Guarda Civil Municipal poderão ser realizadas pela Ouvidoria do Município, subordinada à Secretaria Municipal de Governo.", "comment": "A Ouvidoria funciona como canal de participação e controle externo, com independência e imparcialidade. Até sua implantação, a Ouvidoria do Município pode exercer essas funções.", "memorize": "Ouvidoria = manifestações + transparência.", "trap": "", "juris": ""}, {"n": 10, "title": "INSPETORIA", "legal": "Caput Art. 10. A Inspetoria da Guarda Civil Municipal são órgãos de execução e fiscalização das atividades operacionais, composta pelos Inspetores de 1ª e 2ª Classes. Parágrafo único Compete à Inspetoria da Guarda Civil Municipal: I planejar, coordenar, supervisionar, fiscalizar, distribuir e avaliar as ações desenvolvidas pelas equipes de campo; II garantir a observância das normas operacionais, disciplinares e uso correto de equipamentos e materiais; III apoiar o Comando da Corporação na execução de planos, ordens de serviço e operações especiais; IV elaborar relatórios e propor medidas para subsidiar o planejamento da Instituição; V promover a integração entre as equipes, visando à padronização de procedimentos e ao cumprimento da missão institucional.", "comment": "A Inspetoria executa e fiscaliza as atividades operacionais, supervisiona equipes e apoia o Comando na execução de planos, ordens de serviço e operações especiais.", "memorize": "Inspetores de 1ª e 2ª Classes.", "trap": "", "juris": ""}, {"n": 11, "title": "HIERARQUIA FUNCIONAL", "legal": "Caput Art. 11. A hierarquia funcional da Guarda Civil Municipal, definida no Anexo V desta Lei Complementar, estabelece a ordem de precedência e autoridade no âmbito da Corporação, dispondo sobre a estrutura dos cargos e classes em razão das atividades exercidas por seus integrantes, em conformidade com os princípios da hierarquia e da disciplina. Parágrafo único A posição hierárquica funcional define o grau de autoridade, responsabilidade e comando, refletindo a função desempenhada pelo servidor na organização, além de orientar a distribuição das atribuições administrativas e operacionais, assegurando a clareza das relações de subordinação e a unidade de comando.", "comment": "A hierarquia funcional organiza precedência, autoridade, responsabilidade e comando. O detalhamento aparece no Anexo V.", "memorize": "Autoridade + responsabilidade + comando. BLOCO 02 INGRESSO E FORMAÇÃO ARTS. 12-19 Concurso público, curso de formação e posse", "trap": "", "juris": ""}, {"n": 12, "title": "INVESTIDURA NA CARREIRA", "legal": "Caput Art. 12. A investidura para a carreira de Guarda Civil Municipal dependerá da aprovação em todas as etapas do concurso público e/ou provas e títulos, nos termos da Lei Municipal nº 3.877, de 22 de agosto de 2024.", "comment": "O ingresso depende da aprovação nas etapas do concurso, em articulação com a Lei Municipal nº 3.877/2024.", "memorize": "Aprovação em todas as etapas.", "trap": "", "juris": ""}, {"n": 13, "title": "FASES DO CONCURSO PÚBLICO", "legal": "Caput Art. 13. O concurso público para o ingresso será realizado em fases, distintas e complementares: I prova objetiva e redação de caráter eliminatório e classificatório; II prova de títulos, de caráter classificatório; III teste de aptidão física, de caráter eliminatório e classificatório; IV avaliação psicológica, com análise de perfil para o cargo e habilitação para porte de arma, de caráter eliminatório; V exames médicos, de caráter eliminatório; VI exame toxicológico, de caráter eliminatório; VII investigação social, de caráter eliminatório; VIII curso extensivo de formação profissional, de caráter eliminatório e classificatório. § 1º A aprovação em todas as fases de caráter eliminatório e a obtenção de classificação suficiente nas fases de caráter classificatório são condições indispensáveis para a continuidade do candidato no certame e, em última instância, para a sua investidura no cargo de Guarda Civil Municipal. DISPOSITIVO TEXTO LEGAL § 2º Durante a investigação social deverá ser verificado, dentre outras circunstâncias, se o candidato foi excluído, por inaptidão ou outro motivo de natureza disciplinar ou criminal, dos quadros de forças de segurança pública da União, Estados e Municípios.Seção ÚnicaDo Curso Extensivo de Formação Profissional", "comment": "Enumera oito fases do concurso e identifica quais são eliminatórias, classificatórias ou ambas. É artigo de alta incidência por conter uma lista fechada e classificações.", "memorize": "8 fases do concurso.", "trap": "Prova de títulos é classificatória; várias outras fases são eliminatórias. Leia a natureza de cada fase.", "juris": ""}, {"n": 14, "title": "DEVERES DO ALUNO GCM", "legal": "Caput Art. 14. Os candidatos, ora denominados Aluno GCM, deverão: I comparecer aos cursos, aulas e atividades de treinamento com pontualidade e assiduidade; II submeter-se às provas e testes definidos pelo órgão; III realizar tarefas simples e seguras coadjuvantes aos trabalhos de Guardas Civis Municipais; IV dedicar-se inteiramente ao processo de ensino da GCM para absorção e aprovação no curso.", "comment": "Define os deveres do candidato durante o curso de formação, chamado de Aluno GCM.", "memorize": "Aluno GCM: pontualidade, provas, tarefas seguras e dedicação.", "trap": "", "juris": ""}, {"n": 15, "title": "CANCELAMENTO DA MATRÍCULA NO CURSO", "legal": "Caput Art. 15. Observadas as disposições gerais do Estatuto dos Servidores Públicos do Município de Paracatu, o candidato terá sua matrícula cancelada, será dispensado do curso e reprovado no concurso público quando: I não atingir o mínimo de frequência estabelecida para o curso; II não tiver aproveitamento no curso; III não atingir a capacitação física para o cargo; IV praticar conduta tipificada como infração disciplinar de natureza grave; V não apresentar, no prazo de 30 (trinta) dias a contar do início da realização do curso, a Carteira Nacional de Habilitação (CNH) para condução de veículos na categoria \"B\", de acordo com a legislação de trânsito em vigor. Parágrafo único Os critérios para apuração das condições constantes dos incisos I a IV serão fixados no Estatuto da Guarda Civil Municipal e deverão constar do Edital do concurso público.", "comment": "Lista causas de cancelamento da matrícula e reprovação no concurso durante o curso. A CNH categoria B deve ser apresentada em até 30 dias do início do curso.", "memorize": "CNH B: 30 dias do início do curso.", "trap": "O prazo de 30 dias é para apresentação da CNH B, contado do início do curso.", "juris": ""}, {"n": 16, "title": "AJUDA DE CUSTO DO ALUNO GCM", "legal": "Caput Art. 16. Durante a realização do curso extensivo de formação de Guarda Civil Municipal, os candidatos receberão a denominação de Aluno GCM (AL GCM) e uma ajuda de custo mensal correspondente a 80% (oitenta por cento) do vencimento base fixado para o cargo de Guarda Civil Municipal de 3ª Classe, conforme o Anexo I desta Lei Complementar, não se configurando nesse período qualquer vínculo ou relação de trabalho com a Administração Pública Municipal.", "comment": "Durante o curso, o Aluno GCM recebe ajuda de custo de 80% do vencimento-base do GCM de MCP 3ª Classe. A lei afirma expressamente que não há vínculo de trabalho nesse período.", "memorize": "Ajuda de custo: 80% do GCM 3ª Classe.", "trap": "Ajuda de custo não é vencimento de servidor efetivo durante o curso; a lei nega vínculo de trabalho no período.", "juris": ""}, {"n": 17, "title": "CANDIDATO QUE JÁ É SERVIDOR MUNICIPAL", "legal": "Caput Art. 17. Sendo servidor público efetivo da Administração Municipal, o candidato ficará afastado de seu cargo ou emprego até o término do curso extensivo de formação, sendo facultado ao servidor, durante o período de realização do curso, optar pela remuneração de seu cargo ou pela ajuda de custo estabelecida.", "comment": "Se o candidato já for servidor efetivo municipal, fica afastado e pode optar entre sua remuneração de origem e a ajuda de custo do curso.", "memorize": "Servidor efetivo escolhe remuneração ou ajuda.", "trap": "", "juris": ""}, {"n": 18, "title": "HABILITAÇÃO PARA POSSE", "legal": "Caput Art. 18. Com a conclusão do curso extensivo de formação profissional e a respectiva aprovação do candidato, este será considerado habilitado a tomar posse no concurso de Guarda Civil Municipal, sendo o resultado levado à homologação pelo Prefeito Municipal.", "comment": "A aprovação no curso torna o candidato habilitado à posse, com resultado submetido à homologação pelo Prefeito.", "memorize": "Aprovado no curso = habilitado à posse.", "trap": "", "juris": ""}, {"n": 19, "title": "COMPLEMENTAÇÃO PELO ESTATUTO DA GCM", "legal": "Caput Art. 19. Sem prejuízo das disposições trazidas, o Estatuto da Guarda Civil Municipal trará etapas complementares e exigências do curso extensivo de formação profissional.", "comment": "Reserva ao Estatuto da GCM o detalhamento de etapas complementares e exigências do curso de formação.", "memorize": "Estatuto pode detalhar curso. BLOCO 03 ESTÁGIO PROBATÓRIO ARTS. 20-27 Avaliação, prazos, recurso e estabilidade", "trap": "", "juris": ""}, {"n": 20, "title": "DURAÇÃO E INÍCIO DO ESTÁGIO PROBATÓRIO", "legal": "Caput Art. 20. O servidor nomeado para o cargo de provimento efetivo de Guarda Civil Municipal ficará sujeito a estágio probatório pelo período de 3 (três) anos de efetivo exercício. Parágrafo único O período de estágio probatório terá início em sua contabilização tão somente após o término de todas as etapas do concurso público, englobando, inclusive, o curso extensivo de formação, o teste de aptidão física e a avaliação psicológica, nos termos do § único do art. 6º. da Lei Municipal nº 3.877, de 22 de agosto de 2024.", "comment": "O probatório dura 3 anos de efetivo exercício, mas a contagem só começa depois de concluídas todas as etapas do concurso, conforme a redação local.", "memorize": "Probatório: 3 anos; contagem após todas as etapas.", "trap": "A lei local não conta o probatório desde o curso: a contagem começa após todas as etapas.", "juris": ""}, {"n": 21, "title": "COMISSÃO DE AVALIAÇÃO DO ESTÁGIO", "legal": "Caput Art. 21. A Comissão de Avaliação do Estágio Probatório, constituída para essa finalidade sob a supervisão do setor de Recursos Humanos, terá formação interdisciplinar e deverá ter indicação de, pelo menos, um servidor público vinculado à Superintendência de Segurança Pública e Defesa Social. Parágrafo único A atuação dos membros da Comissão de Avaliação do Estágio Probatório dar-se-á sem prejuízo das atribuições dos cargos dos quais são titulares.", "comment": "A comissão é interdisciplinar, vinculada à supervisão do RH e deve ter pelo menos um servidor ligado à Superintendência de Segurança Pública e Defesa Social.", "memorize": "Comissão interdisciplinar + 1 servidor da Superintendência.", "trap": "", "juris": ""}, {"n": 22, "title": "AVALIAÇÃO DE DESEMPENHO NO PROBATÓRIO", "legal": "Caput Art. 22. Durante o período do estágio probatório, o servidor será submetido a avaliação de desempenho, nos termos do disposto no §4º do artigo 41 da Constituição Federal, com base nos critérios estabelecidos quanto à aptidão, capacitação e perfil profissional, sem prejuízo de outros fatores. § 1º A avaliação de desempenho será realizada pela Comissão de Avaliação do Estágio Probatório ou outra comissão correlata e deverá ser concluída 60 (sessenta) dias antes do prazo final do estágio probatório. § 2º Será assegurado ao servidor a ciência ao parecer exarado pela Comissão de Avaliação do Estágio Probatório, bem como ao recurso voluntário, no prazo de 5 (cinco) dias, se for contrário à sua confirmação no serviço público. § 3º O recurso voluntário será direcionado ao Presidente da Comissão de Avaliação do Estágio Probatório, que decidirá pelo seu deferimento ou indeferimento, devidamente justificado. DISPOSITIVO TEXTO LEGAL § 4º O parecer final da Comissão de Avaliação do Estágio Probatório ou a decisão recursal exarada pelo Presidente da Comissão de Avaliação do Estágio Probatório, resultante da avaliação de desempenho, será submetido à homologação da autoridade competente.", "comment": "Disciplina avaliação, prazos e recurso: conclusão 60 dias antes do fim do probatório e recurso voluntário em 5 dias quando o parecer for desfavorável.", "memorize": "60 dias antes; recurso em 5 dias.", "trap": "Não confunda 60 dias (antecedência da avaliação) com 5 dias (recurso).", "juris": ""}, {"n": 23, "title": "INFORMAÇÕES PRESTADAS PELO COMANDO", "legal": "Caput Art. 23. O Comando da Guarda Civil Municipal deverá subsidiar informações requisitadas pela Comissão de Avaliação do Estágio Probatório para fins de instrução da avaliação de desempenho, podendo delegar as funções dentro das atribuições administrativas internas da corporação.", "comment": "O Comando deve fornecer as informações solicitadas pela Comissão para instruir a avaliação, podendo delegar tarefas administrativas internas.", "memorize": "Comando subsidia a Comissão.", "trap": "", "juris": ""}, {"n": 24, "title": "NÃO APROVAÇÃO NO PROBATÓRIO", "legal": "Caput Art. 24. O servidor não aprovado no estágio probatório para Guarda Civil Municipal será exonerado ou, se já estável em outro cargo efetivo do Município de Paracatu, reconduzido ao cargo ou função pública que anteriormente ocupava.", "comment": "Não aprovado no probatório: exoneração; se o servidor já era estável em outro cargo efetivo municipal, há recondução ao cargo ou função anterior.", "memorize": "Exoneração ou recondução.", "trap": "", "juris": ""}, {"n": 25, "title": "SUSPENSÃO DA CONTAGEM DO PROBATÓRIO", "legal": "Caput Art. 25. O cômputo do prazo de estágio probatório ficará suspenso na hipótese de concessão de quaisquer das licenças ou afastamentos previstos na Lei Complementar nº 05, de 25 de junho de 1991 - Estatuto dos Servidores Públicos do Município de Paracatu, tendo em vista a impossibilidade da efetiva avaliação do desempenho do Guarda Civil Municipal no exercício das atribuições do cargo.", "comment": "Licenças e afastamentos do Estatuto suspendem a contagem do probatório porque impedem avaliação efetiva do desempenho.", "memorize": "Licenças/afastamentos suspendem contagem.", "trap": "", "juris": ""}, {"n": 26, "title": "EXONERAÇÃO DURANTE O PROBATÓRIO", "legal": "Caput Art. 26. Durante o estágio probatório o servidor poderá ser exonerado justificadamente, mediante processo administrativo com garantia ao contraditório e à ampla defesa, se não satisfizer as exigências desta Lei Complementar, no tocante ao desempenho das funções.", "comment": "Admite exoneração justificada durante o probatório, mas exige processo administrativo com contraditório e ampla defesa.", "memorize": "Exoneração exige processo + defesa.", "trap": "", "juris": ""}, {"n": 27, "title": "REGULAMENTAÇÃO DA AVALIAÇÃO", "legal": "Caput Art. 27. A composição e o procedimento de avaliação de desempenho a ser observado pela Comissão de Avaliação do Estágio Probatório e nos casos de exoneração serão estabelecidos em regramento próprio, podendo ser comum ao aplicado aos demais servidores públicos do Município de Paracatu.", "comment": "Remete a composição e o procedimento de avaliação a regramento próprio, que pode ser comum ao dos demais servidores municipais.", "memorize": "Procedimento por regramento próprio. BLOCO 04 CARREIRA E CLASSES ARTS. 28-34 Criação da carreira, investidura e atribuições por classe", "trap": "", "juris": ""}, {"n": 28, "title": "CRIAÇÃO DA CARREIRA E DOS CARGOS", "legal": "Caput Art. 28. Fica instituída a carreira e criados 40 (quarenta) cargos efetivos de Guarda Civil Municipal, com ingresso mediante aprovação em concurso público e/ou provas e títulos, participação de curso extensivo de formação específica, teste de aptidão física e avaliação psicológica, nos termos da Lei Municipal nº 3.877, de 22 de agosto de 2024. Parágrafo único Fica estabelecida reserva de, no mínimo, 20% (vinte por cento) do total de vagas para o cargo de Guarda Civil Municipal para candidatas do sexo feminino.", "comment": "Cria 40 cargos efetivos de GCM e fixa reserva mínima de 20% das vagas para candidatas do sexo feminino.", "memorize": "40 cargos; mínimo 20% para mulheres.", "trap": "A reserva é de no mínimo 20% do total de vagas para candidatas.", "juris": ""}, {"n": 29, "title": "ENQUADRAMENTO INICIAL E ESTABILIDADE", "legal": "Caput Art. 29. O Guarda Civil Municipal nomeado mediante aprovação em concurso público é enquadrado como GCM de 3ª Classe e submetido a estágio probatório durante o período de 3 (três) anos, findo o qual, se aprovado, torna-se estável, permanecendo até atingir requisito para promoção.", "comment": "O ingresso ocorre na 3ª Classe. Após 3 anos de probatório e aprovação, o servidor adquire estabilidade e permanece na classe até preencher requisito de promoção.", "memorize": "Ingresso na 3ª Classe.", "trap": "", "juris": ""}, {"n": 30, "title": "REQUISITOS DE INVESTIDURA", "legal": "Caput Art. 30. Os requisitos básicos de investidura nos cargos efetivos de Guarda Civil Municipal são enumerados pelo art. 7º. da Lei Municipal nº 3.877, de 22 de agosto de 2024.", "comment": "Não repete os requisitos de investidura: remete ao art. 7º da Lei Municipal nº 3.877/2024.", "memorize": "Requisitos estão na Lei 3.877/2024.", "trap": "", "juris": ""}, {"n": 31, "title": "CLASSES DA CARREIRA", "legal": "Caput Art. 31. As Classes dos Guardas Civis Municipais integram o Quadro de Pessoal da Prefeitura Municipal de Paracatu, vinculados à Secretaria Municipal de Governo e à Superintendência de Segurança Pública e Defesa Social, e são dispostas em ordem crescente de precedências, nos seguintes termos: I Guarda Civil Municipal de 3ª Classe (GCM 3CL); II Guarda Civil Municipal de 2ª Classe (GCM 2CL); III Guarda Civil Municipal de 1ª Classe (GCM 1CL); IV Guarda Civil Municipal de Classe Plena (GCM CP); V Guarda Civil Municipal de Classe Distinta (GCM CD); VI Guarda Civil Municipal de Classe Especial (GCM CE).", "comment": "Organiza seis classes em ordem crescente: 3ª, 2ª, 1ª, Classe Plena, Classe Distinta e Classe Especial.", "memorize": "3ª > 2ª > 1ª > Plena > Distinta > Especial.", "trap": "", "juris": ""}, {"n": 32, "title": "ATRIBUIÇÕES COMUNS DAS CLASSES", "legal": "Caput Art. 32. São atribuições comuns aos Guardas Civis Municipais de 3ª a 1ª Classe e de Classe Plena aquelas destinadas ao cumprimento do princípio da universalidade: I executar guarda ostensiva e preventiva visando a proteção à população, bens, serviços e instalações do Município de Paracatu; II tomar conhecimento das ordens existentes a respeito de sua ocupação ao iniciar qualquer serviço para o qual se encontre escalado; III estar atento durante a execução de qualquer serviço; DISPOSITIVO TEXTO LEGAL IV tratar com atenção e urbanidade as pessoas com as quais, em razão de serviço, entrar em contato, ainda quando estas procederem de maneira diversa; V executar ações de sua competência estabelecido na Lei Federal nº 13.022/1cc VI zelar pelo equipamento de radiocomunicação e demais utensílios destinados à consecução das suas atividades; VII zelar pela sua apresentação individual e pessoal, se apresentando descentemente com o uniforme alinhado e higiênico; VIII colaborar e orientar o público em geral, quando necessário; IX executar atividades de socorro e proteção às vítimas de calamidades públicas, participando das ações de defesa civil; X cumprir fielmente as ordens emanadas de seus superiores hierárquicos; XI colaborar com os diversos Órgãos Públicos, nas atividades que lhe dizem respeito; XII orientar, fiscalizar e controlar o trânsito municipal de pedestres e veículos na área de suas atribuições; XIII colaborar na prevenção e combate de incêndios e no suporte básico da vida, quando necessário; XIV exercer a vigilância de edifícios públicos municipais, controlando a entrada de pessoas, adotando providências tendentes a evitar roubos, furtos, incêndios e outros danos na área sob a sua guarda; XV efetuar rondas periódicas de inspeção pelos prédios municipais e imediações, examinando portas, janelas e portões, para assegurar-se de que estão devidamente fechados; XVI impedir a entrada, no prédio ou áreas adjacentes, de pessoas estranhas ou sem autorização, fora de horário de trabalho, convidando-as a se retirarem como medida de segurança; XVII comunicar ao superior imediato qualquer irregularidade ocorrida durante seu plantão, para que sejam tomadas as devidas providências; XVIII zelar pelo prédio e suas instalações, levando ao conhecimento de seu superior qualquer fato que dependa de serviços especializados para reparo e manutenção; XIX dirigir as viaturas da Guarda Civil Municipal para as quais esteja credenciado; XX operar equipamentos tecnológicos que proporcionem maior segurança aos próprios munícipes, como: sistema de monitoramento de alarmes, câmeras de vídeo, dentre outros; XXI executar outras funções correlatas determinadas pelos superiores atinentes ao cargo.", "comment": "Traz o núcleo operacional comum das classes de 3ª a 1ª e Classe Plena: proteção, patrulhamento, trânsito, defesa civil, vigilância, comunicação de irregularidades, viaturas e tecnologia.", "memorize": "Atribuições operacionais comuns.", "trap": "", "juris": ""}, {"n": 33, "title": "CLASSE DISTINTA", "legal": "Caput Art. 33. São atribuições do Guarda Civil Municipal de Classe Distinta: I executar as funções dos Guardas Civis Municipal de 3ª a 1ª Classe e de Classe Plena; II ser o elo entre os Guardas Civis Municipal de 3ª, 2ª, 1ª Classe e a Classe Plena com a Classe Especial; III comandar o turno de serviço na falta de integrante da Classe Especial, Inspetor de 2ª Classe ou Inspetor de 1ª Classe, atentando para as atribuições destes, quando no exercício da função; IV executar outras funções correlatas determinadas pelos superiores atinentes ao cargo.", "comment": "A Classe Distinta acumula as atribuições anteriores, atua como elo hierárquico e pode comandar turno na ausência das autoridades indicadas pela lei.", "memorize": "Distinta = elo + possível comando de turno.", "trap": "", "juris": ""}, {"n": 34, "title": "CLASSE ESPECIAL", "legal": "Caput Art. 34. Ao Guarda Civil Municipal de Classe Especial, caberá as atribuições descritas aos Guardas Civis Municipais de Classe Distinta e comandar o turno de serviço na falta do Subinspetor ou Inspetor, atentando-se para as funções destes, quando no exercício da função.", "comment": "A Classe Especial acumula atribuições da Classe Distinta e pode comandar turno nas MCP ausências previstas no texto legal.", "memorize": "Especial = atribuições da Distinta + comando nas ausências. BLOCO 05 DESENVOLVIMENTO FUNCIONAL ARTS. 35-46 Promoção, progressão e capacitação", "trap": "", "juris": ""}, {"n": 35, "title": "FORMAS DE DESENVOLVIMENTO FUNCIONAL", "legal": "Caput Art. 35. O desenvolvimento funcional da carreira de Guarda Civil Municipal na carreira se dará por promoção e progressão, às quais fará jus apenas o servidor estável.", "comment": "Promoção e progressão são as duas formas de desenvolvimento funcional e, segundo o artigo, somente o servidor estável faz jus a elas.", "memorize": "Só estável: promoção/progressão.", "trap": "O artigo exige estabilidade para promoção e progressão.", "juris": ""}, {"n": 36, "title": "PROMOÇÃO: REGRA GERAL", "legal": "Caput Art. 36. A promoção consiste na evolução vertical na carreira, com a passagem do servidor de uma classe para a imediatamente superior e será concedida a cada 5 (cinco) anos de efetivo serviço na classe, no mês de dezembro, acrescendo-se 8% (oito por cento) ao vencimento-base da classe atualmente ocupada. Parágrafo único Para fins de promoção, serão observados os requisitos estabelecidos no Estatuto da Guarda Civil Municipal.", "comment": "Promoção é evolução vertical para a classe imediatamente superior. A regra combina 5 anos de efetivo serviço na classe, concessão em dezembro e acréscimo de 8% ao vencimento-base.", "memorize": "5 anos + dezembro + 8%.", "trap": "Promoção: 5 anos e 8%; progressão: 730 dias e 1%.", "juris": ""}, {"n": 37, "title": "ORDEM DAS PROMOÇÕES", "legal": "Caput Art. 37. As promoções ocorrerão na seguinte ordem: I o Guarda Civil Municipal de 3ª Classe terá promoção para Guarda Civil Municipal de 2ª Classe após 5 (cinco) anos de efetivo serviço no cargo, contado o tempo de estágio probatório; II o Guarda Civil Municipal que contar com 5 (cinco) anos de efetivo exercício na 2ª Classe será promovido a Guarda Civil Municipal de 1ª Classe; III o Guarda Civil Municipal que contar com 5 (cinco) anos de efetivo exercício na 1ª Classe será promovido a Guarda Civil Municipal de Classe Plena; IV o Guarda Civil Municipal que contar com 5 (cinco) anos de efetivo exercício na Classe Plena será promovido a Guarda Civil Municipal de Classe Distinta; V o Guarda Civil Municipal que contar com 5 (cinco) anos de efetivo exercício na Classe Distinta será promovido a Guarda Civil Municipal de Classe Especial.", "comment": "Desenha a escada promocional, sempre para a classe imediatamente superior, em ciclos de 5 anos, com a regra específica do primeiro avanço contando o estágio probatório.", "memorize": "Cada promoção: 5 anos.", "trap": "", "juris": ""}, {"n": 38, "title": "ESCALONAMENTO DAS PROMOÇÕES", "legal": "Caput Art. 38. A promoção a que se refere o artigo anterior, ocorrerá dentre os integrantes da mesma turma e obedecerá aos percentuais abaixo especificados: I nº 5º ano da data-base, será promovido o primeiro terço dos integrantes da turma, por critério de merecimento, observada a ordem de classificação no curso extensivo de formação; II nº 6º ano da data-base, será promovida a metade dos integrantes remanescentes da turma, também por critério de merecimento, observada a ordem de classificação no curso extensivo de formação; III nº 7º ano da data-base, será promovido o restante dos integrantes da turma, por critério de antiguidade. § 1º Considera-se como data-base a data de ingresso na carreira da Guarda Civil Municipal, não sendo computado, para esse fim, o período de realização do curso extensivo de formação e as demais etapas do concurso público. § 2º Os casos de impedimento à promoção dos integrantes da Guarda Civil Municipal serão regulamentados no Estatuto da Guarda Civil, que deverá estabelecer, de forma expressa, as hipóteses, prazos, procedimentos e efeitos decorrentes, observada a legislação vigente e assegurado o contraditório e a ampla defesa.", "comment": "A promoção da turma é escalonada: primeiro terço no 5º ano, metade dos remanescentes no 6º e restante no 7º. A data-base exclui curso de formação e demais etapas do concurso.", "memorize": "5º ano 1/3; 6º metade remanescente; 7º restante.", "trap": "O escalonamento é 1/3 no 5º ano, metade dos remanescentes no 6º e o restante no 7º.", "juris": ""}, {"n": 39, "title": "BRAVURA E POST MORTEM", "legal": "Caput Art. 39. Poderá ocorrer a promoção a uma classe imediatamente superior a que se encontra por ato de bravura ou post mortem. § 1º Entende-se como promoção por ato de bravura aquela concedida ao servidor em razão de fato que tenha colocado em risco incomum a sua própria vida para a preservação da vida de terceiros, demonstrando coragem e audácia. § 2º Entende-se como promoção post mortem, aquela concedida por reconhecimento do Município de Paracatu, em virtude do óbito do servidor no cumprimento do dever. § 3º As promoções citadas nos parágrafos anteriores são de competência exclusiva do Prefeito Municipal, após apuração e conclusão de procedimento administrativo elaborado pela Comissão Permanente de Gestão de Pessoal com parecer favorável à promoção. § 4º O procedimento administrativo para promoção por ato de bravura terá como requisito de instauração o reconhecimento do fato pela maioria absoluta da Câmara Municipal, de modo a refletir o sentimento de toda a sociedade.", "comment": "Prevê promoções extraordinárias por bravura e post mortem. A decisão é do Prefeito após procedimento; a bravura exige reconhecimento do fato pela maioria absoluta da Câmara para instaurar o procedimento.", "memorize": "Bravura/post mortem; decisão do Prefeito.", "trap": "", "juris": ""}, {"n": 40, "title": "PROGRESSÃO: REGRA GERAL", "legal": "Caput Art. 40. A progressão corresponde a evolução horizontal da carreira, ocorrendo por merecimento, sendo a elevação de um padrão de vencimento imediatamente superior àquele em que o servidor está posicionado, na proporção de 1% (um por cento), conforme o Anexo I desta Lei Complementar.", "comment": "Progressão é evolução horizontal, por merecimento, para padrão de vencimento imediatamente superior, com incremento de 1%.", "memorize": "Progressão = +1% horizontal.", "trap": "Progressão não muda de classe; é horizontal.", "juris": ""}, {"n": 41, "title": "PROGRESSÃO POR MERECIMENTO", "legal": "Caput Art. 41. A Progressão por Merecimento se dará quando atendidas as seguintes exigências: I haver completado 730 (setecentos e trinta) dias de efetivo exercício na classe; II não haver sofrido, nos 6 (seis) meses que antecederem a progressão, pena disciplinar de suspensão; III ter obtido conceito favorável na avaliação de desempenho, apurada por comissão designada para esse fim, com resultado mínimo de 70% (setenta por cento). § 1º O tempo de serviço do servidor que se encontrar afastado do exercício das atribuições do cargo de Guarda Civil Municipal não será computado para efeito do disposto no inciso I deste artigo, exceto nas hipóteses de nomeação para cargo em comissão, e nos casos previstos na legislação municipal como de efetivo exercício. § 2º A contagem de tempo para novo período aquisitivo de direito será iniciada, sempre, no dia seguinte àquele em que o servidor houver completado o período anterior. DISPOSITIVO TEXTO LEGAL § 3º A avaliação de desempenho de que trata o artigo será feita com base em critérios objetivos estabelecidos em Decreto do Prefeito Municipal.", "comment": "Reúne os requisitos da progressão por merecimento: 730 dias, ausência de suspensão nos 6 meses anteriores e avaliação mínima de 70%.", "memorize": "730 dias + sem suspensão 6 meses + 70%.", "trap": "Os três números centrais são 730 dias, 6 meses e 70%.", "juris": ""}, {"n": 42, "title": "PROGRESSÃO E FUNÇÃO/CARGO DE CONFIANÇA", "legal": "Caput Art. 42. O servidor ocupante de cargo em comissão e/ou de função gratificada terá direito à progressão no cargo efetivo de que seja titular.", "comment": "Mesmo em cargo em comissão ou função gratificada, o servidor conserva o direito à progressão no cargo efetivo de que é titular.", "memorize": "Cargo/função de confiança não elimina progressão.", "trap": "", "juris": ""}, {"n": 43, "title": "TEMPOS QUE NÃO CONTAM PARA PROGRESSÃO", "legal": "Caput Art. 43. Não se computarão para os fins de Progressão por Merecimento: I o tempo de serviço em que o servidor estiver à disposição de órgão não integrante da Administração Municipal, sem ônus para o Poder Executivo; II o tempo em que o servidor estiver em gozo de licença sem remuneração.", "comment": "Exclui da contagem para progressão o período à disposição de órgão externo sem ônus para o Executivo e a licença sem remuneração.", "memorize": "Não conta: cessão externa sem ônus + licença sem remuneração.", "trap": "", "juris": ""}, {"n": 44, "title": "AVALIAÇÃO PARA PROGRESSÃO", "legal": "Caput Art. 44. A avaliação de desempenho será efetuada no mês em que o servidor completar 730 (setecentos e trinta) dias de efetivo exercício e referir-se-á ao desempenho do servidor nos últimos vinte e quatro meses. § 1º A avaliação deverá ser exibida ao servidor para que dela tome conhecimento, a fim de suprir as deficiências que forem observadas sobre seu comportamento e atuação, de modo a assegurar-lhe o direito à ampla defesa e ao contraditório. § 2º Será considerado habilitado para obtenção da progressão o servidor que obtiver, no mínimo, 70% (setenta por cento) em cada fator de avaliação de desempenho.", "comment": "A avaliação ocorre quando o servidor completa 730 dias e considera os 24 meses anteriores. Para habilitação, exige pelo menos 70% em cada fator.", "memorize": "Avaliação aos 730 dias; últimos 24 meses; 70% por fator.", "trap": "O mínimo é 70% em cada fator, não apenas uma média global.", "juris": ""}, {"n": 45, "title": "PROGRESSÃO APÓS PROBATÓRIO", "legal": "Caput Art. 45. O servidor só terá direito à progressão de que trata esta subseção após cumprido o estágio probatório.", "comment": "Reforça que a progressão somente pode ser obtida depois de cumprido o estágio probatório.", "memorize": "Progressão somente após probatório.", "trap": "", "juris": ""}, {"n": 46, "title": "CAPACITAÇÃO CONTINUADA", "legal": "Caput Art. 46. A Guarda Civil Municipal instituirá programas permanentes de capacitação e requalificação profissional, visando ao aprimoramento contínuo das competências técnicas, táticas e comportamentais de seus integrantes. § 1º Os programas de capacitação contínua deverão abranger, entre outros, os seguintes temas: I atualização em legislação vigente; II técnicas de policiamento preventivo e comunitário; III uso progressivo da força e técnicas de defesa pessoal; IV atendimento a grupos vulneráveis e mediação de conflitos; V primeiros socorros e atendimento pré-hospitalar; VI tecnologias aplicadas à segurança pública; VII direitos Humanos e ética profissional. § 2º A participação nos programas de capacitação contínua será obrigatória para todos os integrantes da Guarda Civil Municipal, sendo condição para progressão na carreira e manutenção do porte de arma institucional. § 3º A carga horária mínima anual para as atividades de capacitação será definida em regulamento próprio, observadas as diretrizes estabelecidas pelo Estatuto Geral das Guardas Municipais (Lei Federal nº 13.022/2014) e demais normativas aplicáveis. § 4º Os cursos e treinamentos realizados no âmbito dos programas de capacitação contínua poderão ser considerados para fins de progressão por conhecimento, nos termos da", "comment": "Institui capacitação permanente e obrigatória. A participação é condição para progressão e manutenção do porte de arma institucional, segundo a redação da lei.", "memorize": "Capacitação obrigatória; condição para progressão/porte. BLOCO 06 JORNADA E REMUNERAÇÃO ARTS. 47-59 Jornada, vencimentos, vantagens e adicionais", "trap": "", "juris": ""}, {"n": 47, "title": "JORNADA SEMANAL", "legal": "Caput Art. 47. A jornada de trabalho do Guarda Civil Municipal é fixada em 40 (quarenta) horas semanais, mediante escala de revezamento ou de plantão, podendo compreender dias úteis, recessos, finais de semana e feriados, em períodos diurnos e noturnos.", "comment": "Fixa jornada de 40 horas semanais em escalas de revezamento ou plantão, inclusive em fins de semana, feriados e períodos diurnos/noturnos.", "memorize": "40 horas semanais.", "trap": "A jornada é 40 horas semanais, não 30 ou 44.", "juris": ""}, {"n": 48, "title": "FIXAÇÃO DE HORÁRIO E CONVOCAÇÃO", "legal": "Caput Art. 48. O horário de trabalho semanal do Guarda Civil Municipal será fixado pelo Comando da Guarda Civil Municipal, de acordo com a natureza e necessidade do serviço, com a possibilidade de escalas de revezamento e de plantões, os quais poderão sofrer alternância entre si, conforme a necessidade de serviço. Parágrafo único O Guarda Civil Municipal poderá ser convocado a qualquer momento para atendimento de situações de urgência e de emergência ou de necessidade da Administração Pública, desde que sejam coerentes com as atribuições do cargo.", "comment": "O Comando fixa horários conforme a necessidade do serviço. O GCM pode ser convocado para urgência, emergência ou necessidade administrativa coerente com as atribuições do cargo.", "memorize": "Comando fixa escala; convocação em urgência/necessidade.", "trap": "", "juris": ""}, {"n": 49, "title": "VENCIMENTO-BASE E REVISÃO ANUAL", "legal": "Caput Art. 49. O valor do vencimento base para cada classe da Guarda Civil Municipal é fixado conforme o Anexo I desta Lei Complementar. Parágrafo único A tabela de vencimentos dos Guardas Civis Municipais será revista anualmente, em observância ao art. 37, inciso X da Constituição da República Federativa do Brasil e à Lei Municipal nº 2.727, de 15 de junho de 2009, na data base fixada para fins de revisão geral anual dos servidores públicos municipais.", "comment": "O vencimento-base por classe está no Anexo I. A tabela deve ser revista anualmente na data-base da revisão geral dos servidores municipais.", "memorize": "Anexo I + revisão anual.", "trap": "", "juris": ""}, {"n": 50, "title": "REMUNERAÇÃO DE FUNÇÕES GRATIFICADAS", "legal": "Caput Art. 50. Os servidores designados para as funções de Comandante, Subcomandante, Corregedor, Inspetor de 1ª e 2ª Classe e Ouvidor perceberão vencimentos inerentes à sua classe e nível, cumulativamente com a gratificação da função que passará a exercer, conforme o Anexo II desta Lei Complementar.", "comment": "Quem exerce funções de Comandante, Subcomandante, Corregedor, Inspetores e Ouvidor recebe vencimento da classe/nível mais a gratificação da função do Anexo II.", "memorize": "Vencimento da classe/nível + gratificação.", "trap": "", "juris": ""}, {"n": 51, "title": "VANTAGENS REMUNERATÓRIAS", "legal": "Caput Art. 51. Os vencimentos dos servidores Guardas Civis Municipais não excluem a percepção, nos termos da legislação, das seguintes vantagens: I adicional por trabalho extraordinário; II adicional noturno; III gratificação natalina; IV adicional de férias; V adicional de periculosidade.", "comment": "Lista cinco vantagens: trabalho extraordinário, adicional noturno, gratificação natalina, adicional MCP de férias e periculosidade.", "memorize": "5 vantagens.", "trap": "", "juris": ""}, {"n": 52, "title": "LIMITAÇÃO DAS VANTAGENS", "legal": "Caput Art. 52. As vantagens devidas aos servidores Guardas Civis Municipais ficam adstritas as previstas nessa Lei Complementar.", "comment": "Estabelece que as vantagens devidas aos GCMs ficam restritas às previstas na própria LC 198/2025.", "memorize": "Vantagens restritas à LC 198.", "trap": "", "juris": ""}, {"n": 53, "title": "TRABALHO EXTRAORDINÁRIO", "legal": "Caput Art. 53. Os Guardas Civis Municipais estão sujeitos à convocação extraordinária em função de demanda devidamente justificada. § 1º As horas excedentes à carga horária semanal de trabalho poderão ser compensadas com horas de folga na mesma proporção. § 2º Ao invés de compensação com horas de folga, poderá ser pago Adicional por Trabalho Extraordinário ao Guarda Civil Municipal que desempenhar suas funções de modo a exceder ao período normal de trabalho, até o máximo de 2 (duas) horas diárias, as quais serão remuneradas com acréscimo de 50% (cinquenta por cento) sobre o valor da hora normal de trabalho quando realizada em dias úteis e de 60% (sessenta por cento) quando realizadas em domingos, recessos e feriados.", "comment": "A convocação extraordinária pode gerar compensação de horas ou adicional. O pagamento é limitado a 2 horas diárias, com 50% em dias úteis e 60% em domingos, recessos e feriados.", "memorize": "Máx. 2h/dia; 50% útil; 60% domingo/recesso/feriado.", "trap": "Trabalho extraordinário pago: até 2 horas diárias; 50% em dias úteis e 60% em domingos, recessos e feriados.", "juris": ""}, {"n": 54, "title": "ADICIONAL NOTURNO", "legal": "Caput Art. 54. O período compreendido entre 22 (vinte e duas) horas de um dia às 5 (cinco) horas do dia seguinte deverá contemplar adicional noturno, nos mesmos percentuais e moldes previstos no art. 15 da Lei Complementar nº 54, de 23 de maio de 2007. Parágrafo único Na hipótese de eventual alteração na regulamentação ou no percentual do Adicional Noturno aplicável aos Servidores Públicos Municipais de Paracatu, aplicar-se-á automaticamente aos Guardas Civis Municipais.", "comment": "Considera noturno o período das 22h às 5h e remete percentuais e moldes à LC 54/2007, com atualização automática se o regime geral municipal mudar.", "memorize": "Noturno: 22h-5h.", "trap": "O período noturno indicado é 22h às 5h.", "juris": ""}, {"n": 55, "title": "GRATIFICAÇÃO NATALINA", "legal": "Caput Art. 55. A gratificação natalina será paga no valor de 1/12 (um doze avos) da remuneração devida no mês de dezembro, por mês de exercício, nos mesmos moldes e percentuais previstos no art. 19 da Lei Complementar nº 54, de 23 de maio de 2007. Parágrafo único Na hipótese de eventual alteração na regulamentação ou no percentual da Gratificação Natalina aplicável aos Servidores Públicos Municipais de Paracatu, aplicar-se-á automaticamente aos Guardas Civis Municipais.", "comment": "A gratificação natalina segue a regra de 1/12 da remuneração de dezembro por mês de exercício e acompanha alterações futuras do regime municipal referido.", "memorize": "Natalina: 1/12 por mês.", "trap": "", "juris": ""}, {"n": 56, "title": "ADICIONAL DE FÉRIAS", "legal": "Caput Art. 56. O Adicional de Férias será assegurado aos Guardas Civis Municipais no patamar equivalente a um terço da remuneração normal, devendo ser observadas e aplicadas as regras do art. 67 e seguintes do Estatuto dos Servidores Públicos do Munícipio de Paracatu - Lei Complementar nº 5, de 25 de junho de 1991. Parágrafo único Na hipótese de eventual alteração na regulamentação ou no percentual do Adicional de Férias aplicável aos Servidores Públicos Municipais de Paracatu, aplicar-se-á automaticamente aos Guardas Civis Municipais.", "comment": "Assegura adicional de férias de 1/3 da remuneração normal e remete às regras do Estatuto municipal.", "memorize": "Férias: +1/3.", "trap": "", "juris": ""}, {"n": 57, "title": "ADICIONAL DE PERICULOSIDADE", "legal": "Caput Art. 57. Em razão da natureza e especificidade das atribuições desempenhadas, que expõem seus integrantes a riscos diretos e permanentes, fica assegurado aos integrantes da Guarda Civil Municipal o direito a percepção de Adicional de Periculosidade, correspondente a 20% (vinte por cento) do vencimento básico da classe que ocupa. § 1º O Adicional de Periculosidade previsto no caput possui caráter permanente, sendo devido enquanto o servidor estiver no efetivo exercício das funções inerentes as atividades de Guarda Civil Municipal, inclusive quando designado para funções gratificadas ou cargos em comissão dentro da corporação. § 2º O pagamento do Adicional de Periculosidade não será cumulativo com outras vantagens ou gratificações de mesma natureza, devendo prevalecer o percentual mais vantajoso ao servidor, quando houver. § 3º O Adicional de Periculosidade integrará a base de cálculo para férias, gratificação natalina e demais vantagens remuneratórias, nos termos da legislação aplicável.", "comment": "Fixa adicional de periculosidade em 20% do vencimento básico da classe. É devido no efetivo exercício, inclusive em função gratificada/cargo em comissão dentro da corporação, e integra bases remuneratórias indicadas no artigo.", "memorize": "Periculosidade: 20%.", "trap": "Periculosidade = 20% do vencimento básico da classe.", "juris": ""}, {"n": 58, "title": "PERICULOSIDADE NOS AFASTAMENTOS", "legal": "Caput Art. 58. Não fará jus ao Adicional de Periculosidade o integrante da Guarda Civil Municipal que não estiver no efetivo exercício das atribuições inerentes ao cargo, exceto quando o afastamento ocorrer exclusivamente em decorrência de fato ou situação diretamente relacionada ao desempenho de suas funções na corporação. Parágrafo único Para os fins deste artigo, consideram-se afastamentos diretamente relacionados ao desempenho das funções: I licença para tratamento de saúde decorrente de acidente em serviço ou de doença adquirida em razão da atividade; II afastamento para participação em cursos, treinamentos ou capacitações oficiais de interesse da instituição; III outras hipóteses previstas em lei que guardem nexo causal com o exercício das funções de Guarda Civil Municipal.", "comment": "Em regra, afastado das atribuições o servidor perde a periculosidade; o próprio artigo cria exceções quando o afastamento tem nexo com a atividade da GCM.", "memorize": "Afastamento em regra exclui; exceções com nexo funcional.", "trap": "", "juris": ""}, {"n": 59, "title": "REGIME ESPECIAL DA PERICULOSIDADE", "legal": "Caput Art. 59. O Adicional de Periculosidade ora fixado excepciona-se a regra trazida pela Lei Complementar nº 35, de 24 de maio de 2001 para a concessão de Adicional de Periculosidade para os demais servidores públicos municipais, em razão da singularidade da carreira de Guarda Civil Municipal.", "comment": "Afirma que o regime de periculosidade da GCM é exceção ao modelo geral previsto na LC 35/2001, em razão da singularidade da carreira.", "memorize": "Regime especial da GCM. BLOCO 07 CARGOS E FUNÇÕES ARTS. 60-77 Cargos em comissão, funções gratificadas e mandatos", "trap": "", "juris": ""}, {"n": 60, "title": "CARGOS EM COMISSÃO", "legal": "Caput Art. 60. Ficam criados os seguintes cargos, de provimento em comissão, com remuneração fixada no Anexo III desta Lei Complementar: I Comandante; II Subcomandante; III Corregedor; IV Inspetor de 1ª Classe; V Ouvidor.", "comment": "Cria os cargos em comissão de Comandante, Subcomandante, Corregedor, Inspetor de 1ª Classe e Ouvidor, com valores no Anexo III.", "memorize": "5 tipos de cargos em comissão.", "trap": "", "juris": ""}, {"n": 61, "title": "PERÍODO INICIAL DE 3 ANOS", "legal": "Caput Art. 61. Durante os 3 (três) primeiros anos de funcionamento da Guarda Civil Municipal, os cargos em comissão poderão ser ocupados por profissionais externos ao quadro de pessoal da Guarda Civil Municipal, conforme disposto no §1º do art. 15 da Lei Federal nº 13.022, de 2014, com o objetivo de assegurar a imediata efetividade, coordenação e controle dos serviços prestados, desde que não tenha sido excluído, por inaptidão ou outro motivo de natureza disciplinar ou criminal, dos quadros de forças de segurança pública da União, Estados e Municípios.", "comment": "Nos três primeiros anos de funcionamento, admite ocupação dos cargos em comissão por profissionais externos, com a restrição disciplinar/criminal indicada no artigo.", "memorize": "Externos: somente nos 3 primeiros anos.", "trap": "A possibilidade de profissionais externos é transitória: três primeiros anos.", "juris": ""}, {"n": 62, "title": "REQUISITOS DOS CARGOS EM COMISSÃO", "legal": "Caput Art. 62. São requisitos de nomeação para os cargos de provimento em comissão: I de Comandante e Subcomandante: I.a) possuir experiência ou formação na área de segurança pública, I.b) diploma de curso superior reconhecido pelo Ministério da Educação; e I.c) apresentar certidão negativa de antecedentes criminais. II de Corregedor: II.a) possuir experiência ou formação na área de segurança pública, II.b) graduação em Direito, ou, excepcionalmente, comprovação de notório conhecimento jurídico; e II.c) apresentar certidão negativa de antecedentes criminais. III de Inspetor de 1ª Classe: III.a) possuir experiência ou formação na área de segurança pública; III.b) possuir, no mínimo, no ensino médio completo; e III.c) apresentar certidão negativa de antecedentes criminais. IV de Ouvidor: IV.a) possuir experiência ou formação na área de segurança pública; IV.b) possuir, no mínimo, no ensino médio completo; e IV.c) apresentar certidão negativa de antecedentes criminais.", "comment": "Define requisitos diferenciados por cargo em comissão. Comandante/Subcomandante exigem superior; Corregedor exige Direito ou notório conhecimento jurídico; Inspetor de 1ª e Ouvidor exigem ao menos ensino médio, além dos demais requisitos legais.", "memorize": "Requisitos variam conforme cargo.", "trap": "", "juris": ""}, {"n": 63, "title": "CONCEITO DE FUNÇÃO GRATIFICADA", "legal": "Caput Art. 63. Considera-se função gratificada, no âmbito da Guarda Civil Municipal, o encargo de natureza transitória e de confiança, atribuído a integrante efetivo da corporação, para o exercício de atividades de comando, chefia, coordenação, supervisão, assessoramento ou outra função de natureza estratégica.", "comment": "Função gratificada é encargo transitório e de confiança para servidor efetivo da corporação, voltado a comando, chefia, coordenação, supervisão, assessoramento ou função estratégica.", "memorize": "FG = encargo transitório de confiança para efetivo.", "trap": "", "juris": ""}, {"n": 64, "title": "CONVERSÃO EM FUNÇÕES GRATIFICADAS", "legal": "Caput Art. 64. Decorrido o prazo previsto no art. 61, os cargos de provimento em comissão serão convertidos em funções gratificadas, as quais serão exercidas exclusivamente por servidores efetivos integrantes do quadro de pessoal da Guarda Civil Municipal, nos termos do art. 15 da Lei Federal nº 13.022/2014.", "comment": "Depois do período inicial do art. 61, os cargos em comissão são convertidos em funções gratificadas, exclusivas de servidores efetivos da GCM.", "memorize": "Após 3 anos: comissão -> FG.", "trap": "Após o período inicial, as funções gratificadas são exclusivas de servidores efetivos da GCM.", "juris": ""}, {"n": 65, "title": "INSPETOR DE 2ª CLASSE: PRIMEIRA DESIGNAÇÃO", "legal": "Caput Art. 65. Ficam criadas as funções gratificadas de Inspetor de 2ª Classe, que deverá ser designadas logo após a homologação do primeiro concurso público de seleção de Guardas Civis Municipais, devendo serem preenchidas, em sua primeira formação, seguindo a ordem de classificação final estabelecida após a conclusão do curso extensivo de formação profissional. Parágrafo único A observância da ordem de classificação final para fins da designação prevista no caput aplica-se exclusivamente à primeira turma da Guarda Civil Municipal, não gerando direito adquirido à designação para as turmas subsequentes.", "comment": "Cria funções gratificadas de Inspetor de 2ª Classe. Na primeira formação, a designação segue a classificação final da primeira turma, sem direito adquirido para turmas seguintes.", "memorize": "1ª turma: classificação final para Inspetor 2ª.", "trap": "", "juris": ""}, {"n": 66, "title": "VALOR DA GRATIFICAÇÃO DE FUNÇÃO", "legal": "Caput Art. 66. O exercício de função gratificada implicará percepção de gratificação de função, cujo valor é fixado conforme Anexo II desta Lei Complementar.", "comment": "A função gratificada gera gratificação conforme os percentuais do Anexo II.", "memorize": "Percentuais no Anexo II.", "trap": "", "juris": ""}, {"n": 67, "title": "DIREITOS DO OCUPANTE DE FUNÇÃO GRATIFICADA", "legal": "Caput Art. 67. O Guarda Civil Municipal que exerça função gratificada mantém todos os direitos e vantagens assegurados aos demais Guardas Civis Municipais, sem prejuízo de sua remuneração específica.", "comment": "O ocupante de função gratificada mantém os direitos e vantagens dos demais GCMs, além da remuneração específica da função.", "memorize": "Mantém direitos e vantagens.", "trap": "", "juris": ""}, {"n": 68, "title": "ACÚMULO DE FUNÇÕES GRATIFICADAS", "legal": "Caput Art. 68. É permitida a acumulação de mais de uma função gratificada pelo mesmo Guarda Civil Municipal, desde que não haja conflito entre as atribuições ou prejuízo à eficiência administrativa. Parágrafo único As gratificações devidas pelo exercício de funções gratificadas não são cumuláveis, devendo o Guarda Civil Municipal, quando designado para o exercício de funções em acúmulo, optar pela gratificação que considerar mais vantajosa.", "comment": "É possível acumular mais de uma função se não houver conflito ou prejuízo à eficiência, mas as gratificações não se acumulam: o servidor escolhe a mais vantajosa.", "memorize": "Pode acumular função, não gratificação.", "trap": "Pode haver acúmulo de funções, mas não soma das gratificações.", "juris": ""}, {"n": 69, "title": "REQUISITOS DAS FUNÇÕES GRATIFICADAS", "legal": "Caput Art. 69. A função gratificada será exercida exclusivamente por servidor ocupante de cargo efetivo da Guarda Civil Municipal, observados os seguintes critérios para a nomeação ao encargo: I para a função de Comandante: I.a) ser, no mínimo, Guarda Civil Municipal de Classe Plena, ou, na ausência deste, ocupar a maior graduação existente dentre os integrantes da Guarda Civil Municipal; I.b) possuir diploma registrado de curso superior reconhecido pelo Ministério da Educação; I.c) possuir conduta ilibada e idônea; I.d) estar enquadrado, no mínimo, no BOM comportamento; I.e) não possuir antecedentes criminais condenatórios, administrativos e sociais; I.f) não ter ficado à disposição de outros órgãos exercendo funções diversas das de Guarda Civil Municipal nos últimos 2 (dois) anos; I.g) não ter se afastado num período de 2 (dois) anos que, somados, ultrapassem 90 (noventa) dias, excetuando-se os dias de afastamento por licença nojo, gala, maternidade, paternidade, acidentária, requisição judicial, doação de sangue, licença prêmio, férias e afastamento para concorrer a cargo eletivo conforme legislação pertinente. II para a função de Subcomandante: II.a) ser, no mínimo, Guarda Civil Municipal de Classe Plena, ou, na ausência deste, ocupar a maior graduação existente dentre os integrantes da Guarda Civil Municipal; II.b) possuir diploma registrado de curso superior reconhecido pelo Ministério da Educação; II.c) estar enquadrado, no mínimo, no BOM comportamento; II.d) ter conduta ilibada e notória; II.e) não possuir antecedentes criminais condenatórios, administrativos e sociais. III para a função de Corregedor: III.a) ser, no mínimo, Guarda Civil Municipal de Classe Plena, ou, na ausência deste, ocupar a maior graduação existente dentre os integrantes da Guarda Civil Municipal; III.b) possuir diploma de graduação em Direito reconhecido pelo Ministério da Educação, ou, excepcionalmente, comprovação de notório conhecimento jurídico; III.c) possuir conduta ilibada e idônea; III.d) estar enquadrado, no mínimo, no BOM comportamento; DISPOSITIVO TEXTO LEGAL III.e) não possuir antecedentes criminais condenatórios, administrativos e sociais. IV para as funções de Inspetor de 1ª e 2ª Classe e Ouvidor: IV.a) ser, no mínimo, Guarda Civil Municipal de Classe Plena, ou, na ausência deste, ocupar a maior graduação existente dentre os integrantes da Guarda Civil Municipal; IV.b) possuir conduta ilibada e idônea; IV.c) estar enquadrado, no mínimo, no BOM comportamento; IV.d) não possuir antecedentes criminais condenatórios, administrativos e sociais.", "comment": "É um dos artigos mais extensos e cobrados: fixa requisitos para Comandante, Subcomandante, Corregedor, Inspetores e Ouvidor, incluindo classe mínima, escolaridade, comportamento e antecedentes.", "memorize": "Classe mínima + escolaridade + comportamento + antecedentes.", "trap": "O Corregedor tem requisito de graduação em Direito ou, excepcionalmente, notório conhecimento jurídico.", "juris": ""}, {"n": 70, "title": "COMPETÊNCIA PARA NOMEAR/DESIGNAR/EXONERAR", "legal": "Caput Art. 70. A nomeação, designação e exoneração dos cargos em comissão e das funções gratificadas são de competência exclusiva do Chefe do Poder Executivo.", "comment": "Nomeação, designação e exoneração dos cargos em comissão e funções gratificadas pertencem exclusivamente ao Chefe do Poder Executivo.", "memorize": "Competência exclusiva do Prefeito.", "trap": "", "juris": ""}, {"n": 71, "title": "CARGOS SEM MANDATO DETERMINADO", "legal": "Caput Art. 71. Os cargos e funções de Comandante, Subcomandante e de Inspetor de 1ª e 2ª Classe não são sujeitos ao regime de mandato com prazo determinado. § 1º Na hipótese de exoneração ou desligamento do Comandante, o Subcomandante em exercício, em assunção de atribuições, apresentará lista tríplice ao Chefe do Poder Executivo, no prazo de 5 (cinco) dias, para a escolha do novo Comandante. § 2º Na hipótese de exoneração ou desligamento do Subcomandante ou dos Inspetores de 1ª e 2ª Classe, o Comandante deverá apresentar, no prazo de 5 (cinco) dias, o(s) nome(s) dos novos indicados, para posterior nomeação ou designação pelo Chefe do Poder Executivo.", "comment": "Comandante, Subcomandante e Inspetores de 1ª/2ª Classe não têm mandato fixo. Em desligamentos, a lei estabelece prazo de 5 dias para lista tríplice ou novas indicações.", "memorize": "Sem mandato fixo; prazo de 5 dias em vacância indicada.", "trap": "Comandante/Subcomandante/Inspetores não têm mandato fixo; Corregedor/Ouvidor têm.", "juris": ""}, {"n": 72, "title": "MANDATO DO CORREGEDOR E OUVIDOR", "legal": "Caput Art. 72. Os cargos e funções de Corregedor e Ouvidor da Guarda Civil Municipal sujeitam-se a mandato pelo período de 4 (quatro) anos, passível de recondução. Parágrafo único Em caso de renúncia do mandato, devidamente fundamentada pelo servidor renunciante, ou a vacância do cargo por outro motivo, poderá o Prefeito Municipal proceder nova nomeação, para o cumprimento do tempo restante ao término do mandato.", "comment": "Corregedor e Ouvidor têm mandato de 4 anos, com possibilidade de recondução. Em vacância, nova nomeação completa o tempo restante.", "memorize": "Corregedor/Ouvidor: mandato 4 anos.", "trap": "Mandato de Corregedor e Ouvidor = 4 anos, com recondução.", "juris": ""}, {"n": 73, "title": "PERDA DE MANDATO", "legal": "Caput Art. 73. O Corregedor e o Ouvidor somente perderão o mandato por decisão da maioria absoluta da Câmara Municipal, mediante processo de perda de mandato, fundada em razão relevante e específica, nos termos do §2º do art. 13 da Lei Federal nº 13.022, de 8 de agosto de 2014. § 1º Consideram-se razões relevantes e específicas para fins deste artigo: I prática de falta grave funcional, a ser apurada no curso do processo de perda de mandato; II condenação criminal transitada em julgado, incompatível com o exercício da função; III descumprimento reiterado dos deveres inerentes ao cargo ou por abuso de poder; IV perda dos requisitos exigidos em lei para a investidura na função; V ato que comprometa a independência, a imparcialidade ou a moralidade no desempenho das funções. § 2º O processo de perda de mandato será instaurado mediante representação fundamentada, apresentada por vereador ou pelo Prefeito Municipal e recebida pela Mesa Diretora da Câmara Municipal, que, em decisão motivada, verificará a existência de indícios mínimos de autoria e materialidade para a sua instauração. § 3º Uma vez instaurado o processo de perda de mandato, a Mesa Diretora designará relator dentre os vereadores, que será responsável pela condução da instrução processual. § 4º Para a completa elucidação dos fatos e garantia do devido processo legal, o relator terá amplos poderes de instrução, podendo, entre outras medidas, requisitar documentos e informações de órgãos públicos e privados, determinar a realização de perícias, ouvir testemunhas, limitadas a 3 (três) por fato apurado, e realizar diligências, assegurando-se o contraditório e a ampla defesa em todas as etapas da instrução. § 5º Concluída a fase de instrução, o relator notificará o Corregedor ou o Ouvidor representado para apresentar sua defesa final no prazo de 10 (dez) dias, contados da notificação sobre a conclusão da instrução e o acesso integral aos autos do processo. § 6º Após a apresentação da defesa final ou o decurso do prazo, o relator emitirá seu parecer conclusivo sobre os fatos e a indicação de procedência ou improcedência da representação, no prazo de até 15 (quinze) dias úteis, submetendo-o à Mesa Diretora. § 7º O parecer do relator e a defesa final serão submetidos ao Plenário da Câmara Municipal, que, após discussão, deliberará por votação nominal e aberta. § 8º O processo de perda de mandato deverá ser concluído no prazo máximo e improrrogável de 90 (noventa) dias, contados do recebimento da representação pela Mesa Diretora, sob pena de seu arquivamento imediato. DISPOSITIVO TEXTO LEGAL § 9º Na hipótese de o relator ou qualquer membro da Mesa Diretora se encontrar em situação de impedimento ou suspeição, deverá declarar-se e ser substituído conforme o Regimento Interno da Câmara Municipal. § 10 A Mesa Diretora da Câmara Municipal decidirá sobre os casos omissos e os demais procedimentos internos para a condução do processo de perda de mandato.", "comment": "A perda de mandato de Corregedor/Ouvidor exige maioria absoluta da Câmara e processo próprio, com hipóteses, instrução, defesa e prazos detalhados.", "memorize": "Perda: maioria absoluta; defesa 10 dias; parecer 15 dias úteis; máximo 90 dias.", "trap": "Perda de mandato não é ato unilateral simples: há Câmara, maioria absoluta, processo e prazos.", "juris": ""}, {"n": 74, "title": "ALTERAÇÃO DA LEI MUNICIPAL Nº 3.877/2024", "legal": "Caput Art. 74. Fica alterado o art. 11 e seu parágrafo único da Lei Municipal nº 3.877, de 22 de agosto de 2024, que passam a vigorar com as seguintes redações: \"Art. 11. Após a conversão dos cargos de provimento em comissão em funções gratificadas, estas somente poderão ser designadas dentre os membros efetivos de carreira da Guarda Civil Municipal. Parágrafo único Nos 3 (três) primeiros anos de funcionamento, enquanto existirem os cargos de provimento em comissão vinculados à Guarda Civil Municipal, esta poderá ser dirigida por profissionais estranhos ao seu quadro, escolhidos preferencialmente dentre pessoas com experiência ou formação na área de segurança ou defesa social.\"", "comment": "Altera o art. 11 da Lei 3.877/2024: após a conversão para funções gratificadas, estas serão destinadas a efetivos; nos três primeiros anos, a direção pode ser exercida por externos nos termos do texto.", "memorize": "Altera art. 11 da Lei 3.877/2024.", "trap": "", "juris": ""}, {"n": 75, "title": "PRIMEIRA COMPOSIÇÃO DA GCM", "legal": "Caput Art. 75. Para a primeira composição, durante os 3 (três) primeiros anos de funcionamento da Guarda Civil Municipal, a nomeação do Comandante, Subcomandante, Corregedor, Inspetor de 1ª Classe e Ouvidor será de livre escolha e competência exclusiva do Chefe do Poder Executivo Municipal, observados os requisitos específicos de cada cargo previstos nesta Lei Complementar.", "comment": "Na primeira composição e durante os três primeiros anos, a escolha dos cargos indicados é MCP livre e exclusiva do Prefeito, respeitados os requisitos da LC.", "memorize": "Primeiros 3 anos: livre escolha do Prefeito.", "trap": "", "juris": ""}, {"n": 76, "title": "ESCOLHA DO COMANDANTE E INDICAÇÕES", "legal": "Caput Art. 76. A escolha do Comandante da Guarda Civil Municipal será realizada a partir de lista tríplice encaminhada pelo Comandante em exercício ao Chefe do Poder Executivo até o dia 10 de janeiro do primeiro ano do mandato deste, composta por servidores de carreira que atendam aos requisitos imprescindíveis ao cargo, acompanhada da respectiva ficha funcional e demais informações pertinentes, cabendo ao Prefeito Municipal nomear um dos indicados ou reconduzir o atual Comandante. § 1º O Comandante nomeado indicará dentre os servidores efetivos da Guarda Civil Municipal, os ocupantes dos cargos de Corregedor, Subcomandante, Inspetores de 1ª e 2ª Classe e Ouvidor, para posterior nomeação pelo Chefe do Poder Executivo, podendo, alternativamente, propor a recondução dos que já se encontrem em exercício. DISPOSITIVO TEXTO LEGAL § 2º As indicações previstas neste artigo deverão observar, além dos requisitos legais e regulamentares, os princípios da legalidade, impessoalidade, moralidade, publicidade e eficiência. § 3º Caso o Comandante não encaminhe a lista tríplice no prazo regulamentar, caberá ao Chefe do Poder Executivo Municipal adotar as providências necessárias à sua formação, garantida a observância dos requisitos legais. § 4º A vacância do cargo de Comandante implicará na assunção imediata de suas funções pelo Subcomandante, até a nomeação de novo titular.", "comment": "Após a fase inicial, a escolha do Comandante envolve lista tríplice até 10 de janeiro do primeiro ano do mandato do Prefeito; o Comandante indica outras funções, submetidas à nomeação do Chefe do Executivo.", "memorize": "Lista tríplice até 10 de janeiro.", "trap": "Lista tríplice do Comandante: até 10 de janeiro do primeiro ano do mandato do Prefeito.", "juris": ""}, {"n": 77, "title": "SUBSTITUIÇÕES TEMPORÁRIAS", "legal": "Caput Art. 77. As substituições temporárias de qualquer dos cargos ou funções previstos neste Capítulo serão realizadas conforme dispuser o Estatuto da Guarda Civil Municipal.", "comment": "Substituições temporárias ficam remetidas ao Estatuto da Guarda Civil Municipal.", "memorize": "Substituições: Estatuto da GCM. BLOCO 08 ATRIBUIÇÕES PROFISSIONAIS ARTS. 78-85 Competências dos cargos e funções de comando", "trap": "", "juris": ""}, {"n": 78, "title": "ATRIBUIÇÕES DO COMANDANTE", "legal": "Caput Art. 78. O Comandante da Guarda Civil Municipal é a autoridade máxima da corporação, responsável pela direção, coordenação e controle das atividades administrativas e operacionais, e tem como atribuições: I representar a corporação em todos os assuntos relativos a ela; II constituir comissões; III estabelecer a política de emprego da Guarda Civil Municipal; IV decidir questões administrativas; V assessorar o Chefe do Poder Executivo, o Secretário de Governo e Superintendente de Segurança Pública nos assuntos relativos à preservação da ordem pública; VI classificar e transferir GCM`s para funções que visem melhor eficiência e eficácia; VII delegar as atribuições de sua competência; VIII definir o acesso às promoções por critérios de antiguidade ou merecimento; IX zelar pela conduta civil e profissional do pessoal da Guarda Civil Municipal; DISPOSITIVO TEXTO LEGAL X apresentar propostas ou emitir pareceres sobre assuntos administrativos e operacionais que devam ser apreciados pelo Chefe do Poder Executivo, pelo Secretário de Governo e/ou pelo Superintendente de Segurança Pública; XI elaborar os planos e diretrizes de trabalho dos integrantes da Guarda Civil Municipal, que permitam a consecução dos seus objetivos; XII zelar pelo cumprimento de toda legislação necessária ao desenvolvimento do trabalho da GCM; XIII prestar contas, sempre que requeridas por órgãos externos, quando necessário, das atividades realizadas pela instituição; XIV apresentar as necessidades orçamentárias para a realização das atividades planejadas para o próximo exercício e solicitar suplementação caso haja necessidade; XV promover condições para proporcionar treinamento, aprimoramento e aperfeiçoamento dos GCM`s, visando a melhoria dos serviços prestados, através de cursos de formação, capacitação e de reciclagem; XVI comandar a escolta pessoal do Prefeito e do Vice-Prefeito quando realizada por GCM`s; XVII conceder e suspender o porte de arma aos servidores da GCM; XVIII desempenhar outras atividades atinentes à função.", "comment": "O Comandante é a autoridade máxima e concentra direção, representação, política de emprego, decisões administrativas, planejamento, orçamento, capacitação, escolta institucional e competências sobre porte de arma indicadas no texto.", "memorize": "Comandante = autoridade máxima.", "trap": "", "juris": ""}, {"n": 79, "title": "ATRIBUIÇÕES DO CORREGEDOR", "legal": "Caput Art. 79. O Corregedor da Guarda Civil Municipal é a segunda mais alta patente na hierarquia funcional, responsável pela fiscalização da atividade funcional, pela apuração de infrações disciplinares e pela preservação da ética, da hierarquia e da disciplina, tendo como atribuições: I auxiliar no planejamento e supervisão das atividades dos Guardas Civis Municipais exercendo o controle quanto ao comportamento ético, social e funcional dos integrantes da corporação; II receber e apurar as comunicações e informações sobre os casos que, em tese configurem infrações; III realizar fiscalizações e inspeções; IV auxiliar e acompanhar as avaliações dos servidores em estágio probatório; V controlar o uso do armamento e treinamento da GCM na forma da legislação vigente; VI controlar e fiscalizar o uso da força pela Guarda Civil Municipal na forma da lei; VII articular-se, mediante comunicação aos órgãos competentes para inquérito policial sobre todo e qualquer ato cometido pelos integrantes da GCM; VIII proceder de ofício, ao tomar conhecimento sobre denúncias, reclamações e representações, promovendo, de imediato, a instauração de procedimento adequado, requisitando informações, recolhendo provas e indícios e adotando medidas administrativas, cíveis ou criminais cabíveis; IX promover o acompanhamento de inquérito policial ou processo judicial em que haja envolvimento de integrante da Guarda Civil Municipal; X requisitar ou solicitar o comparecimento de funcionários que exerçam funções nas repartições da GCM; XI requisitar ou solicitar os documentos necessários a instruírem os respectivos procedimentos, inclusive de outros órgãos públicos; DISPOSITIVO TEXTO LEGAL XII manter atualizado, por todos os meios de identificação, o registro de antecedentes funcionais dos integrantes da Instituição; XIII adotar, de ofício ou quando provocado, quaisquer outras providências necessárias ao fiel desempenho das atribuições que lhe são conferidas nesta Lei.", "comment": "O Corregedor é a segunda autoridade e exerce fiscalização funcional, apuração disciplinar, controle de armamento e uso da força, inspeções e acompanhamento de procedimentos envolvendo integrantes da GCM.", "memorize": "Corregedor = segunda autoridade.", "trap": "", "juris": ""}, {"n": 80, "title": "FORMA DE ESCOLHA DO CORREGEDOR", "legal": "Caput Art. 80. O cargo de Corregedor da Guarda Civil Municipal será de provimento em comissão, de livre escolha do Chefe do Poder Executivo, na primeira composição da GCM e, posteriormente, quando de sua conversão em função gratificada, será escolhido pelo Comandante da Guarda Civil Municipal, respeitados os requisitos do inciso III do art. 69 desta Lei Complementar.", "comment": "Na primeira composição, o Corregedor é cargo em comissão de livre escolha do Prefeito; após a conversão em função gratificada, sua escolha passa a observar o modelo do Comandante e os requisitos do art. 69, III.", "memorize": "Primeiro comissão; depois FG.", "trap": "", "juris": ""}, {"n": 81, "title": "ATRIBUIÇÕES DO SUBCOMANDANTE", "legal": "Caput Art. 81. O Subcomandante da Guarda Civil Municipal é a terceira autoridade da corporação, responsável pela organização, execução e controle dos serviços operacionais no sentido de cumprir o planejamento elaborado pelo Comando, tendo como atribuições: I auxiliar, assessorar e apoiar o Comandante da GCM em todos os assuntos relativos à instituição; II coordenar, fiscalizar, supervisionar todo serviço operacional da Guarda Civil Municipal; III assistir e representar o Comandante da Guarda Civil Municipal, quando requisitado; IV coordenar todas as atividades desempenhadas pela Guarda Civil Municipal; V acompanhar e fiscalizar a elaboração do relatório minucioso, semestral, do comportamento dos Guardas Civis Municipais para a Corregedoria; VI analisar propostas da Corregedoria, buscando benefícios para a Corporação, seus comandados e a população, primando sempre pela prestação de serviço de excelência e a qualidade de vida do servidor; VII enviar ao Comandante da Guarda Civil Municipal, relatório minucioso das atividades da Instituição; VIII coordenar os meios logísticos, transportes, comunicações, uniformes, armas e munições; IX desempenhar outras atividades atinentes à função.", "comment": "O Subcomandante é a terceira autoridade e atua na coordenação/fiscalização operacional, apoio ao Comandante, logística e relatórios institucionais.", "memorize": "Subcomandante = terceira autoridade.", "trap": "", "juris": ""}, {"n": 82, "title": "ATRIBUIÇÕES DO OUVIDOR", "legal": "Caput Art. 82. O Ouvidor da Guarda Civil Municipal tem como atribuições: I receber e dar o devido encaminhamento às denúncias, reclamações, críticas, elogios, representação e notícias sobre irregularidades, omissões ou atos considerados ilegais, arbitrários, desonestos, indecorosos, antiéticos ou que violem os direitos humanos individuais ou coletivos atribuídos aos integrantes da GCM; II articular-se com a Corregedoria e com os demais órgãos e instituições municipais para o recebimento e apuração de fatos vinculados aos agentes e no desempenho de suas funções; III encaminhar sugestões sobre o funcionamento dos serviços da Guarda Civil Municipal; IV auxiliar no estudo, planejamento e desenvolvimento de políticas públicas de segurança; V informar os resultados aos interessados, garantindo-lhe orientações e respostas; VI estabelecer canais de comunicação com a comunidade que venham a facilitar e agilizar o fluxo das informações e solução de seus pleitos.", "comment": "A Ouvidoria recebe manifestações, articula-se com a Corregedoria, sugere melhorias, participa do planejamento de políticas e cria canais de comunicação com a comunidade.", "memorize": "Ouvidor = canal com sociedade.", "trap": "", "juris": ""}, {"n": 83, "title": "ATRIBUIÇÕES DO INSPETOR DE 2ª CLASSE", "legal": "Caput Art. 83. O cargo de Inspetor de 2ª Classe da Guarda Civil Municipal relaciona-se às atividades de supervisão do efetivo a ele subordinado, visando o cumprimento das determinações superiores e tem como atribuições: I auxiliar o Inspetor de 1ª Classe da Guarda Civil Municipal, quando solicitado, substituindo-o em seus impedimentos legais ou sua falta; II monitorar todos os Guardas Civis Municipais sob sua subordinação, comunicando todas as irregularidades que verificar; III transmitir à equipe sob seu comando as ordens e determinações de serviço; IV receber todos os relatórios de serviços de sua equipe e encaminhar ao seu superior imediato; V realizar pesquisas de materiais, equipamentos e tecnologias para aprimoramento e modernização dos serviços da atividade de Segurança Pública afetos à Guarda Civil Municipal; VI desempenhar atividades de supervisão e ronda nos postos da Guarda Civil Municipal; VII distribuir as tarefas aos seus subordinados e/ou transmitir ordens e orientação de seus superiores hierárquicos; VIII orientar e fiscalizar a atuação dos seus subordinados no trato com o público e nas situações decorrentes de suas atividades; IX orientar e fiscalizar o uso de armamento e equipamentos utilizados pela Guarda Civil Municipal; X escriturar o Livro de Ocorrências da área a que está jurisdicionado, zelando pela exatidão das informações; XI distribuir o efetivo empregado nas missões definidas pelo escalão superior, fiscalizando o cumprimento das ordens emanadas; XII apoiar o efetivo sob seu comando, orientando-as para o correto atendimento e encaminhamento das ocorrências; XIII fiscalizar a boa apresentação de seus subordinados e de suas respectivas viaturas e equipamentos; DISPOSITIVO TEXTO LEGAL XIV promover a aproximação com a comunidade e exigir o mesmo de seus subordinados; XV acompanhar o atendimento de ocorrências de seus subordinados quando necessário; XVI zelar para que as normas e diretrizes vigentes sejam fielmente cumpridas, bem como as determinações do escalão superior; XVII promover a coesão de seus subordinados entre si e com o escalão superior, mantendo a harmonia; XVIII cumprir as normas vigentes da instituição visando ao desenvolvimento das atividades administrativas e operacionais atinentes à Guarda Civil Municipal; XIX zelar pela disciplina de seus subordinados; XX executar outras funções correlatas determinadas pelos superiores atinentes ao cargo.", "comment": "O Inspetor de 2ª Classe supervisiona o efetivo subordinado, transmite ordens, recebe relatórios, fiscaliza armamento/equipamentos, disciplina, apresentação e aproximação comunitária.", "memorize": "Inspetor 2ª = supervisão direta.", "trap": "", "juris": ""}, {"n": 84, "title": "ATRIBUIÇÕES GERAIS DO INSPETOR DE 1ª CLASSE", "legal": "Caput Art. 84. O cargo de Inspetor de 1ª Classe da Guarda Civil Municipal relaciona-se ao gerenciamento das competências da GCM visando a preservação da ordem pública nos limites estabelecidos pelas normas vigentes e pelas diretrizes delineadas pelo Comando, tendo como atribuições gerais: I ser o elo entre o Comando da Guarda Civil Municipal e os demais integrantes; II coordenar, fiscalizar e supervisionar o patrulhamento, policiamento e o efetivo sob seu comando; III promover ações de preservação da ordem pública no Município de Paracatu, cumprindo e fazendo cumprir os planos, normas e ordens emanadas do escalão superior; IV estabelecer, em sua área de responsabilidade, as suas prioridades, submetendo-as ao escalão superior para acompanhamento; V exercer a fiscalização do material zelando pela manutenção das dotações e pela sua conservação; VI zelar pela unidade e uniformidade de treinamento e administração quanto ao efetivo sob seu comando; VII elaborar os documentos necessários à avaliação das atividades operacionais conforme as normas estabelecidas pelo escalão superior; VIII proceder a visitas de controle e de apoio técnico, orientando as atividades, avaliando a eficiência operacional, o grau de disciplina, o adestramento dos subordinados, bem como a manutenção do material sob sua responsabilidade; IX no âmbito de suas responsabilidades, manter contato com os órgãos públicos, autoridades militares e civis de sua área para assuntos relativos à execução de suas atribuições; X comandar diretamente as operações cuja importância, gravidade ou complexidade o exijam, em razão do efetivo a ser empregado, da possibilidade de repercussão ou da gravidade; XI estar atento ao acompanhamento de situações sazonais ligados à segurança pública que surjam na área de atuação, efetuando planejamentos e empregos necessários, mesmo que mediante realocação de meios; XII estabelecer normas para o horário de trabalho dos subordinados de forma que estes possam comparecer, escalonada e periodicamente, à rendição de serviço nos diversos turnos, e fiscalizar seu cumprimento; XIII incentivar os Inspetores de 2ª Classe à troca de informações, planejamento e execução do policiamento de modo integrado; DISPOSITIVO TEXTO LEGAL XIV buscar, incessantemente, a aproximação com a comunidade por meio de contatos com o cidadão, lideranças comunitárias e de entidades ou organizações nela inseridas, bem como estimular seus Subinspetores a fazerem o mesmo em suas áreas de atuação; XV supervisionar a execução das atividades operacionais mantendo-as em níveis de efetivo e viaturas planejados; XVI estar em condições de informar ao escalão superior sobre as ocorrências graves ou passíveis de repercussão atendidas ou em andamento no âmbito de seu Comando; XVII cumprir e fazer cumprir as normas vigentes da Instituição visando o desenvolvimento das atividades administrativas e operacionais atinentes à Guarda Civil Municipal; XVIII assistir e representar o Comandante da GCM, quando requisitado; XIX analisar as propostas da Corregedoria, de modo que venha trazer benefícios para a Corporação, seus comandados e a população, primando sempre pela prestação de serviço de excelência; XX executar outras funções correlatas determinadas pelos superiores atinentes ao cargo.", "comment": "O Inspetor de 1ª Classe exerce gerenciamento intermediário: coordena patrulhamento, fiscaliza efetivo e materiais, planeja operações e mantém interlocução com o Comando e comunidade.", "memorize": "Inspetor 1ª = gerenciamento e coordenação.", "trap": "", "juris": ""}, {"n": 85, "title": "ÁREAS DO INSPETOR DE 1ª CLASSE", "legal": "Caput Art. 85. Além das atribuições comuns aos Inspetores de 1ª Classe, compete-lhes as atribuições administrativa, logística, educacional, operacional e de trânsito, de acordo com a área de atuação de cada um deles. § 1º São atribuições do Inspetor Administrativo, Logístico e Educacional: I cuidar da área de Recursos Humanos; II controlar e acompanhar todo andamento de portarias, processos e procedimentos administrativos; III controlar o patrimônio, armamento e equipamentos; IV assistir e representar o Comandante da Guarda Civil Municipal, quando requisitado; V ter ciência de todas as atividades desempenhadas pela Guarda Civil Municipal; VI emitir relatório minucioso semestralmente, do comportamento dos GCM`s para a Corregedoria; VII analisar propostas da Corregedoria, visando benefícios para a corporação, seus comandados e a população, primando sempre pela prestação de serviço de excelência e a qualidade de vida do servidor; VIII coordenar os meios logísticos, alusivos a transportes, comunicações, uniformes, armas e munições; IX coordenar as atividades de ensino e treinamento da Guarda Civil Municipal; X desempenhar outras atividades atinentes à função. § 2º São atribuições do Inspetor Operacional: I coordenar o patrulhamento e policiamento urbano; II fiscalizar todo serviço operacional da Guarda Civil Municipal; III assistir e representar o Comandante da Guarda Civil Municipal, quando requisitado; IV programar medidas de prevenção e monitoramento de áreas de risco e vigilância eletrônica; V produzir e enviar ao Comandante da Guarda Civil Municipal, relatório minucioso das atividades operacionais da Guarda Civil Municipal, quando se fizer necessário; DISPOSITIVO TEXTO LEGAL VI assessorar na decisão final das questões decorrentes de deliberações adotadas pelos seus subordinados; VII programar o plano de segurança do município dentro de sua competência de ação; VIII programar plano de avaliação e monitoramento de grau de risco específico para cada equipamento sob sua guarda; IX desempenhar outras atividades atinentes à função. § 3º O Inspetor de Trânsito é o profissional responsável por zelar pela segurança, organização e fluidez do trânsito em conformidade com o Código de Trânsito Brasileiro - CTB, através da fiscalização, educação e controle do trânsito urbano, cabendo-lhe, como atribuições, ainda: I propiciar a formação e capacitação periódica dos integrantes da equipe de trânsito, assegurando a atualização constante em normas de trânsito, técnicas operacionais e atendimento ao público; II orientar os membros da equipe quanto às práticas de segurança viária, ética profissional e procedimentos administrativos, promovendo a excelência no serviço prestado à comunidade; III coordenar as atividades operacionais da equipe de trânsito, estabelecendo escalas de serviço, supervisionando o cumprimento das atribuições e avaliando o desempenho individual e coletivo; IV verificar o cumprimento das normas de trânsito, como uso do cinto de segurança, respeito aos limites de velocidade e sinalizações; V aplicar multas e autuações em caso de infrações; VI controlar o tráfego de veículos e pedestres; VII orientar motoristas e pedestres em situações de trânsito intenso, acidentes ou eventos especiais; VIII organizar o tráfego em locais estratégicos, como cruzamentos e áreas próximas a escolas; IX realizar campanhas educativas e de conscientização para motoristas, pedestres e ciclistas; X promover palestras e ações educativas em escolas e comunidades; XI atender emergências relacionadas ao trânsito; XII auxiliar na remoção de veículos envolvidos em acidentes ou que obstruem vias públicas; XIII dar suporte a órgãos de emergência, como bombeiros e polícia, em incidentes no trânsito; XIV inspecionar vias públicas; XV identificar problemas na sinalização, pavimentação e iluminação das vias; XVI levar ao conhecimento do Comandante a necessidade de notificação dos órgãos responsáveis para que sejam feitos reparos e melhorias no trânsito tão logo seja detectado; XVII garantir que o trânsito flua de forma segura e ordenada, respeitando as leis de trânsito; XVIII atuar em conjunto com outros órgãos para melhorias no trânsito; XIX desempenhar outras atividades atinentes à função.", "comment": "Especializa o Inspetor de 1ª Classe em três áreas: administrativa/logística/educacional, operacional e trânsito, com atribuições específicas para cada eixo.", "memorize": "3 eixos: administrativo/logístico/educacional; operacional; trânsito. BLOCO 09 DISPOSIÇÕES FINAIS ARTS. 86-90 Exercício superior, integração normativa, anexos e vigência", "trap": "", "juris": ""}, {"n": 86, "title": "EXERCÍCIO DE CARGO SUPERIOR", "legal": "Caput Art. 86. O Guarda Civil Municipal designado para o cargo hierarquicamente superior ao seu, perceberá o salário e vantagens correspondente ao exercício desse cargo somente se vier a exercê-lo por um período igual ou superior a 30 (trinta) dias.", "comment": "O servidor designado para cargo hierarquicamente superior só recebe o salário e vantagens correspondentes se o exercício durar 30 dias ou mais.", "memorize": "Cargo superior: remuneração se >=30 dias.", "trap": "O marco para remuneração do cargo superior é exercício por período igual ou superior a 30 dias.", "juris": ""}, {"n": 87, "title": "APLICAÇÃO SUBSIDIÁRIA DE OUTRAS LEIS", "legal": "Caput Art. 87. Aplicar-se-á o Estatuto dos Servidores Públicos do Município de Paracatu e a Lei Complementar nº 54, de 23 de maio de 2007 - Plano de Cargos e Carreiras dos Servidores da Prefeitura Municipal de Paracatu, naquilo que não for contrário ao disposto nessa Lei.", "comment": "Aplica subsidiariamente o Estatuto dos Servidores e a LC 54/2007, desde que não contrariem a LC 198/2025.", "memorize": "Aplicação subsidiária.", "trap": "", "juris": ""}, {"n": 88, "title": "DENOMINAÇÃO “POLÍCIA MUNICIPAL”", "legal": "Caput Art. 88. A Guarda Civil Municipal poderá ser denominada como Polícia Municipal, em razão de sua legitimidade constitucional como integrante do Sistema Único de Segurança Pública (SUSP), conforme previsto no artigo 144 da Constituição Federal.", "comment": "O texto municipal autoriza a denominação “Polícia Municipal”. Contudo, há atualização jurisprudencial posterior do STF que deve ser estudada em conjunto com o texto local.", "memorize": "Texto local x STF 2026: atenção.", "trap": "O texto municipal deve ser lido com a jurisprudência posterior do STF sobre a nomenclatura “Polícia Municipal”.", "juris": "Atenção: o texto municipal do art. 88 continua reproduzido acima porque é a redação oficial consultada. Posteriormente, o STF decidiu, em abril de 2026, que municípios não podem substituir a denominação “Guarda Municipal” por “Polícia Municipal”. Ao mesmo tempo, o 2026 Tema 656 reconhece a constitucionalidade de ações de segurança urbana pelas Guardas, inclusive policiamento ostensivo e comunitário, respeitadas as competências dos demais órgãos e excluída atividade de polícia judiciária."}, {"n": 89, "title": "ANEXOS INTEGRANTES DA LEI", "legal": "Caput Art. 89. São partes integrantes dessa Lei Complementar: I o Anexo I - Promoções e Progressões da Carreira de Guarda Civil Municipal; II o Anexo II - Funções Gratificadas da Guarda Civil Municipal; III o Anexo IIII Cargos de Provimento em Comissão; IV o Anexo IV - Quadro Hierárquico da Carreira da Guarda Civil Municipal; V o Anexo V - Hierarquia Funcional da Guarda Civil Municipal.", "comment": "Declara os cinco anexos como partes integrantes da lei. O texto do artigo registra “Anexo IIII”, enquanto o próprio documento apresenta “ANEXO III” na sequência.", "memorize": "5 anexos.", "trap": "O texto do art. 89 escreve “Anexo IIII”; preserve a literalidade em questões de lei seca, mas reconheça que o documento apresenta o Anexo III.", "juris": ""}, {"n": 90, "title": "VIGÊNCIA", "legal": "Caput Art. 90. Esta Lei Complementar entra em vigor na data de sua publicação.", "comment": "Estabelece vigência imediata: a lei entrou em vigor na data de sua publicação, em 23/12/2025.", "memorize": "Vigência: publicação. PARTE FINAL Anexos - leitura dirigida Os anexos integram a LC 198/2025 por força do art. 89. Para revisão final, concentre-se em hierarquia, quantitativos, percentuais e valores previstos no texto-base. Anexo II - Funções gratificadas FUNÇÃO QTD. GRATIFICAÇÃO Comandante 100% Subcomandante 80% Corregedor 80% Inspetor 1ª Classe 60% Inspetor 2ª Classe 50% Ouvidor 40% Anexo III - Cargos em comissão CARGO QTD. VENCIMENTO Comandante R$ 8.500,00 Subcomandante R$ 7.000,00 Corregedor R$ 7.000,00 Inspetor 1ª Classe R$ 5.850,00 Ouvidor R$ 4.500,00 ANEXOS Hierarquias da carreira e funcional Anexo IV - Hierarquia da carreira POSIÇÃO CLASSE 1º Classe Especial 2º Classe Distinta 3º Classe Plena 4º 1ª Classe 5º 2ª Classe 6º 3ª Classe Anexo V - Hierarquia funcional POSIÇÃO DENOMINAÇÃO 1º Comandante 2º Corregedor 3º Subcomandante 4º Inspetor de 1ª Classe 5º Inspetor de 2ª Classe 6º Ouvidor 7º GCM Classe Especial 8º GCM Classe Distinta 9º GCM Classe Plena 10º GCM 1ª Classe 11º GCM 2ª Classe 12º GCM 3ª Classe ANEXO I O Anexo I contém a tabela completa de promoções, progressões e vencimentos por classe e referência (A a S). Para valores atualizados, confira o texto oficial compilado e eventuais revisões gerais posteriores.", "trap": "", "juris": ""}];
const QUESTIONS=[{"n": 1, "q": "A LC 198/2025 define progressão como:", "options": [{"letter": "A", "text": "passagem de uma classe à imediatamente superior"}, {"letter": "B", "text": "evolução horizontal para referência/padrão superior"}, {"letter": "C", "text": "mudança de função gratificada"}, {"letter": "D", "text": "promoção por bravura"}], "answer": "B", "explanation": "evolução horizontal para referência/padrão superior."}, {"n": 2, "q": "Integram a estrutura administrativa da GCM, EXCETO:", "options": [{"letter": "A", "text": "Comando"}, {"letter": "B", "text": "Corregedoria"}, {"letter": "C", "text": "Ouvidoria"}, {"letter": "D", "text": "Tribunal Disciplinar"}], "answer": "D", "explanation": "Tribunal Disciplinar."}, {"n": 3, "q": "O controle interno é exercido pela:", "options": [{"letter": "A", "text": "Ouvidoria"}, {"letter": "B", "text": "Corregedoria"}, {"letter": "C", "text": "Câmara Municipal"}, {"letter": "D", "text": "Inspetoria"}], "answer": "B", "explanation": "Corregedoria."}, {"n": 4, "q": "O concurso é composto por quantas fases enumeradas no art. 13?", "options": [{"letter": "A", "text": "6"}, {"letter": "B", "text": "7"}, {"letter": "C", "text": "8"}, {"letter": "D", "text": "9"}], "answer": "C", "explanation": "8."}, {"n": 5, "q": "A CNH categoria B deve ser apresentada no prazo de:", "options": [{"letter": "A", "text": "10 dias"}, {"letter": "B", "text": "20 dias"}, {"letter": "C", "text": "30 dias"}, {"letter": "D", "text": "60 dias"}], "answer": "C", "explanation": "30 dias."}, {"n": 6, "q": "A ajuda de custo do Aluno GCM corresponde a:", "options": [{"letter": "A", "text": "50%"}, {"letter": "B", "text": "60%"}, {"letter": "C", "text": "80%"}, {"letter": "D", "text": "100%"}], "answer": "C", "explanation": "80%."}, {"n": 7, "q": "O estágio probatório dura:", "options": [{"letter": "A", "text": "2 anos"}, {"letter": "B", "text": "3 anos"}, {"letter": "C", "text": "4 anos"}, {"letter": "D", "text": "5 anos"}], "answer": "B", "explanation": "3 anos."}, {"n": 8, "q": "A avaliação final do probatório deve ser concluída:", "options": [{"letter": "A", "text": "30 dias antes"}, {"letter": "B", "text": "45 dias antes"}, {"letter": "C", "text": "60 dias antes"}, {"letter": "D", "text": "90 dias antes"}], "answer": "C", "explanation": "60 dias antes."}, {"n": 9, "q": "O recurso voluntário contra parecer desfavorável no probatório tem prazo de:", "options": [{"letter": "A", "text": "3 dias"}, {"letter": "B", "text": "5 dias"}, {"letter": "C", "text": "10 dias"}, {"letter": "D", "text": "15 dias"}], "answer": "B", "explanation": "5 dias."}, {"n": 10, "q": "A lei cria quantos cargos efetivos de GCM?", "options": [{"letter": "A", "text": "20"}, {"letter": "B", "text": "30"}, {"letter": "C", "text": "40"}, {"letter": "D", "text": "60"}], "answer": "C", "explanation": "40."}, {"n": 11, "q": "A reserva mínima de vagas para candidatas é de:", "options": [{"letter": "A", "text": "10%"}, {"letter": "B", "text": "15%"}, {"letter": "C", "text": "20%"}, {"letter": "D", "text": "30%"}], "answer": "C", "explanation": "20%."}, {"n": 12, "q": "A classe inicial da carreira é:", "options": [{"letter": "A", "text": "1ª Classe"}, {"letter": "B", "text": "2ª Classe"}, {"letter": "C", "text": "3ª Classe"}, {"letter": "D", "text": "Classe Plena"}], "answer": "C", "explanation": "3ª Classe."}, {"n": 13, "q": "A promoção, em regra, ocorre a cada:", "options": [{"letter": "A", "text": "2 anos"}, {"letter": "B", "text": "3 anos"}, {"letter": "C", "text": "4 anos"}, {"letter": "D", "text": "5 anos"}], "answer": "D", "explanation": "5 anos."}, {"n": 14, "q": "O acréscimo associado à promoção do art. 36 é de:", "options": [{"letter": "A", "text": "1%"}, {"letter": "B", "text": "5%"}, {"letter": "C", "text": "8%"}, {"letter": "D", "text": "10%"}], "answer": "C", "explanation": "8%."}, {"n": 15, "q": "A progressão do art. 40 corresponde a:", "options": [{"letter": "A", "text": "1%"}, {"letter": "B", "text": "2%"}, {"letter": "C", "text": "5%"}, {"letter": "D", "text": "8%"}], "answer": "A", "explanation": "1%."}, {"n": 16, "q": "Para progressão por merecimento, o período-base é de:", "options": [{"letter": "A", "text": "365 dias"}, {"letter": "B", "text": "540 dias"}, {"letter": "C", "text": "730 dias"}, {"letter": "D", "text": "1.095 dias"}], "answer": "C", "explanation": "730 dias."}, {"n": 17, "q": "A avaliação para progressão exige no mínimo:", "options": [{"letter": "A", "text": "50%"}, {"letter": "B", "text": "60%"}, {"letter": "C", "text": "70%"}, {"letter": "D", "text": "80%"}], "answer": "C", "explanation": "70%."}, {"n": 18, "q": "A jornada semanal é de:", "options": [{"letter": "A", "text": "30 h"}, {"letter": "B", "text": "36 h"}, {"letter": "C", "text": "40 h"}, {"letter": "D", "text": "44 h"}], "answer": "C", "explanation": "40 h."}, {"n": 19, "q": "O trabalho extraordinário pago é limitado, em regra, a:", "options": [{"letter": "A", "text": "1 h/dia"}, {"letter": "B", "text": "2 h/dia"}, {"letter": "C", "text": "3 h/dia"}, {"letter": "D", "text": "4 h/dia"}], "answer": "B", "explanation": "2 h/dia."}, {"n": 20, "q": "O adicional noturno abrange, segundo a lei:", "options": [{"letter": "A", "text": "20h-4h"}, {"letter": "B", "text": "21h-5h"}, {"letter": "C", "text": "22h-5h"}, {"letter": "D", "text": "23h-6h"}], "answer": "C", "explanation": "22h-5h."}, {"n": 21, "q": "O adicional de periculosidade é de:", "options": [{"letter": "A", "text": "10%"}, {"letter": "B", "text": "15%"}, {"letter": "C", "text": "20%"}, {"letter": "D", "text": "30%"}], "answer": "C", "explanation": "20%."}, {"n": 22, "q": "Nos três primeiros anos, cargos em comissão podem ser ocupados por:", "options": [{"letter": "A", "text": "somente GCMs estáveis"}, {"letter": "B", "text": "profissionais externos, observadas as condições legais"}, {"letter": "C", "text": "somente policiais militares"}, {"letter": "D", "text": "somente servidores federais"}], "answer": "B", "explanation": "profissionais externos, observadas as condições legais."}, {"n": 23, "q": "O mandato do Corregedor e do Ouvidor é de:", "options": [{"letter": "A", "text": "2 anos"}, {"letter": "B", "text": "3 anos"}, {"letter": "C", "text": "4 anos"}, {"letter": "D", "text": "5 anos"}], "answer": "C", "explanation": "4 anos."}, {"n": 24, "q": "A defesa final no processo do art. 73 tem prazo de:", "options": [{"letter": "A", "text": "5 dias"}, {"letter": "B", "text": "10 dias"}, {"letter": "C", "text": "15 dias"}, {"letter": "D", "text": "30 dias"}], "answer": "B", "explanation": "10 dias."}, {"n": 25, "q": "O processo de perda de mandato do art. 73 deve ser concluído em até:", "options": [{"letter": "A", "text": "30 dias"}, {"letter": "B", "text": "60 dias"}, {"letter": "C", "text": "90 dias"}, {"letter": "D", "text": "120 dias"}], "answer": "C", "explanation": "90 dias."}, {"n": 26, "q": "A lista tríplice do art. 76 deve ser encaminhada até:", "options": [{"letter": "A", "text": "10 de janeiro"}, {"letter": "B", "text": "31 de janeiro"}, {"letter": "C", "text": "1º de março"}, {"letter": "D", "text": "30 de junho"}], "answer": "A", "explanation": "10 de janeiro."}, {"n": 27, "q": "O Comandante é, segundo a lei:", "options": [{"letter": "A", "text": "segunda autoridade"}, {"letter": "B", "text": "terceira autoridade"}, {"letter": "C", "text": "autoridade máxima"}, {"letter": "D", "text": "órgão de controle externo"}], "answer": "C", "explanation": "autoridade máxima."}, {"n": 28, "q": "O Corregedor é definido no art. 79 como:", "options": [{"letter": "A", "text": "segunda mais alta autoridade/patente funcional"}, {"letter": "B", "text": "órgão externo sem poder disciplinar"}, {"letter": "C", "text": "subordinado à Ouvidoria"}, {"letter": "D", "text": "autoridade exclusivamente de trânsito"}], "answer": "A", "explanation": "segunda mais alta autoridade/patente funcional."}, {"n": 29, "q": "Para receber remuneração do cargo hierarquicamente superior, o art. 86 exige exercício por:", "options": [{"letter": "A", "text": "10 dias ou mais"}, {"letter": "B", "text": "15 dias ou mais"}, {"letter": "C", "text": "20 dias ou mais"}, {"letter": "D", "text": "30 dias ou mais"}], "answer": "D", "explanation": "30 dias ou mais."}, {"n": 30, "q": "Sobre o art. 88 e a atualização de 2026, é correto afirmar:", "options": [{"letter": "A", "text": "o STF autorizou a troca do nome para Polícia Municipal em todo país"}, {"letter": "B", "text": "o STF vedou a substituição da denominação Guarda Municipal por Polícia Municipal"}, {"letter": "C", "text": "o STF extinguiu as guardas municipais"}, {"letter": "D", "text": "o STF proibiu policiamento comunitário pelas guardas"}], "answer": "B", "explanation": "o STF vedou a substituição da denominação Guarda Municipal por Polícia Municipal."}];
const BLOCKS=[[1, "Estrutura e Organização", "1–11", "Objeto, conceitos, comando, controles e hierarquia"], [2, "Ingresso e Formação", "12–19", "Concurso público, curso de formação e posse"], [3, "Estágio Probatório", "20–27", "Avaliação, prazos, recurso e estabilidade"], [4, "Carreira e Classes", "28–34", "Criação da carreira, investidura e atribuições por classe"], [5, "Desenvolvimento Funcional", "35–46", "Promoção, progressão e capacitação"], [6, "Jornada e Remuneração", "47–59", "Jornada, vencimentos, vantagens e adicionais"], [7, "Cargos e Funções", "60–77", "Cargos em comissão, funções gratificadas e mandatos"], [8, "Atribuições Profissionais", "78–85", "Competências dos cargos e funções de comando"], [9, "Disposições Finais", "86–90", "Exercício superior, integração normativa, anexos e vigência"]];
const NUMBERS=[["40", "cargos efetivos"], ["20%", "reserva mínima para candidatas"], ["80%", "ajuda de custo do Aluno GCM"], ["30 dias", "CNH B após início do curso"], ["3 anos", "estágio probatório"], ["60 dias", "avaliação antes do término"], ["5 dias", "recurso do probatório"], ["5 anos + 8%", "promoção"], ["730 dias", "base da progressão por merecimento"], ["70%", "mínimo na avaliação"], ["1%", "incremento da progressão"], ["40h", "jornada semanal"], ["2h/dia", "máx. de extra paga"], ["50% / 60%", "extra útil / domingo-recesso-feriado"], ["22h–5h", "período noturno"], ["20%", "periculosidade"], ["4 anos", "mandato Corregedor/Ouvidor"], ["10 / 15 / 90", "defesa / parecer / conclusão art. 73"], ["10 jan.", "lista tríplice art. 76"], ["30 dias", "exercício superior art. 86"]];
const ANNEX2=[["Comandante", "1", "100%"], ["Subcomandante", "1", "80%"], ["Corregedor", "1", "80%"], ["Inspetor 1ª Classe", "3", "60%"], ["Inspetor 2ª Classe", "6", "50%"], ["Ouvidor", "1", "40%"]];
const ANNEX3=[["Comandante", "1", "R$ 8.500,00"], ["Subcomandante", "1", "R$ 7.000,00"], ["Corregedor", "1", "R$ 7.000,00"], ["Inspetor 1ª Classe", "3", "R$ 5.850,00"], ["Ouvidor", "1", "R$ 4.500,00"]];
const HIER=["Classe Especial", "Classe Distinta", "Classe Plena", "1ª Classe", "2ª Classe", "3ª Classe"];
const FUNC=["Comandante", "Corregedor", "Subcomandante", "Inspetor 1ª Classe", "Inspetor 2ª Classe", "Ouvidor", "GCM Classe Especial", "GCM Classe Distinta", "GCM Classe Plena", "GCM 1ª Classe", "GCM 2ª Classe", "GCM 3ª Classe"];

const app=document.querySelector('#app');let tab='inicio';let filter='todos';const done=new Set(JSON.parse(localStorage.getItem('mcpDone')||'[]'));const fav=new Set(JSON.parse(localStorage.getItem('mcpFav')||'[]'));let qScore=0,qAnswered=new Set();
const e=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function blockOf(n){return BLOCKS.find(b=>{let[a,z]=b[2].split('–').map(Number);return n>=a&&n<=z})}
function save(){localStorage.setItem('mcpDone',JSON.stringify([...done]));localStorage.setItem('mcpFav',JSON.stringify([...fav]))}
function home(){let pct=Math.round(done.size/90*100);return `<section class="hero"><div class="eyebrow">Reta final • mobile first</div><h2>Domine a LC 198/2025 <span style="color:var(--gold)">artigo por artigo.</span></h2><p>Use busca, marque artigos revisados, favorite pontos difíceis e resolva as 30 questões sem sair da página.</p><div class="progress"><i style="width:${pct}%"></i></div><div class="stats"><div class="stat"><strong>${done.size}</strong><span>artigos revisados</span></div><div class="stat"><strong>${pct}%</strong><span>progresso</span></div><div class="stat"><strong>${fav.size}</strong><span>favoritos</span></div></div></section><h2 class="section-title">Mapa da lei</h2><div class="grid blocks">${BLOCKS.map(b=>`<div class="block-card" onclick="goArticles(${b[0]})"><div class="block-num">${String(b[0]).padStart(2,'0')}</div><div><h3>${e(b[1])}</h3><p>Arts. ${b[2]} • ${e(b[3])}</p></div></div>`).join('')}</div><h2 class="section-title">Recuperação rápida</h2><div class="card"><div style="font-weight:900;color:var(--gold);line-height:1.8">20% · 30 dias · 80% · 3 anos · 60 dias · 5 dias · 5 anos · 8% · 730 dias · 70% · 1% · 40h · 2h · 50%/60% · 22h–5h · 20% · 4 anos · 10/15/90 dias</div></div>`}
function articles(){return `<div class="search"><input id="searchInput" placeholder="Buscar artigo, prazo, palavra-chave..." oninput="renderArticles()"><div class="filters">${['todos','favoritos',...BLOCKS.map(b=>'bloco '+b[0])].map(x=>`<button class="chip ${filter==x?'active':''}" onclick="setFilter('${x}')">${x}</button>`).join('')}</div></div><div id="articleList"></div>`}
function renderArticles(){let el=document.querySelector('#articleList');if(!el)return;let q=(document.querySelector('#searchInput')?.value||'').toLowerCase().trim();let arr=ARTICLES.filter(a=>{let b=blockOf(a.n);let ok=filter==='todos'||filter==='favoritos'&&fav.has(a.n)||filter.startsWith('bloco ')&&b&&b[0]==Number(filter.split(' ')[1]);let hay=`${a.n} ${a.title} ${a.legal} ${a.comment} ${a.memorize} ${a.trap}`.toLowerCase();return ok&&(!q||hay.includes(q))});el.innerHTML=arr.length?arr.map(a=>{let b=blockOf(a.n);return `<article class="card article" id="art-${a.n}"><button class="article-head" onclick="this.parentElement.classList.toggle('open')"><span class="artno">Art. ${a.n}</span><span><b>${e(a.title)}</b><small>Bloco ${String(b?.[0]||'').padStart(2,'0')} • ${e(b?.[1]||'')}</small></span><span>⌄</span></button><div class="article-body"><div class="tagbox legal"><strong>Texto legal</strong>${e(a.legal)}</div>${a.comment?`<div class="tagbox comment"><strong>Comentário MCP</strong>${e(a.comment)}</div>`:''}${a.memorize?`<div class="tagbox memo"><strong>Memorize</strong>${e(a.memorize)}</div>`:''}${a.trap?`<div class="tagbox trap"><strong>Pegadinha</strong>${e(a.trap)}</div>`:''}${a.juris?`<div class="tagbox juris"><strong>Jurisprudência / atualização</strong>${e(a.juris)}</div>`:''}<div class="done-row"><button class="done ${done.has(a.n)?'checked':''}" onclick="toggleDone(${a.n})">${done.has(a.n)?'✓ Revisado':'Marcar como revisado'}</button><button class="done fav ${fav.has(a.n)?'checked':''}" onclick="toggleFav(${a.n})">★</button></div></div></article>`}).join(''):`<div class="empty">Nenhum artigo encontrado.</div>`}
function numbers(){return `<h2 class="section-title">Números que merecem marca-texto</h2><p class="note">Concentre a memorização nestes valores e confirme cada um no artigo correspondente.</p><div class="nums">${NUMBERS.map(n=>`<div class="numcard"><strong>${e(n[0])}</strong><span>${e(n[1])}</span></div>`).join('')}</div>`}
function questions(){return `<section class="hero"><div class="eyebrow">Treino</div><h2>30 questões de fixação</h2><p>Resolva sem consultar a lei. Cada resposta mostra a correção da apostila.</p><div class="stat" style="margin-top:12px"><strong id="score">${qScore}/${qAnswered.size}</strong><span>acertos / respondidas</span></div></section><div style="height:12px"></div>${QUESTIONS.map(q=>`<div class="card qcard"><h3>${q.n}. ${e(q.q)}</h3>${q.options.map(o=>`<button class="option" data-q="${q.n}" data-l="${o.letter}" onclick="answer(this,${q.n},'${q.answer}')"><b>${o.letter})</b> ${e(o.text)}</button>`).join('')}<div class="feedback" id="fb-${q.n}"><b>Gabarito: ${q.answer}</b> • ${e(q.explanation)}</div></div>`).join('')}`}
function table(rows,h3){return `<div class="table-wrap"><table><thead><tr>${h3.map(x=>`<th>${e(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr>${r.map(x=>`<td>${e(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`}
function annexes(){return `<h2 class="section-title">Anexos • leitura dirigida</h2><div class="card"><h3>Anexo II — Funções gratificadas</h3>${table(ANNEX2,['Função','Qtd.','Gratificação'])}</div><div style="height:10px"></div><div class="card"><h3>Anexo III — Cargos em comissão</h3>${table(ANNEX3,['Cargo','Qtd.','Vencimento'])}</div><div style="height:10px"></div><div class="card"><h3>Anexo IV — Quadro hierárquico da carreira</h3><ol>${HIER.map(x=>`<li>${e(x)}</li>`).join('')}</ol></div><div style="height:10px"></div><div class="card"><h3>Anexo V — Hierarquia funcional</h3><ol>${FUNC.map(x=>`<li>${e(x)}</li>`).join('')}</ol></div><p class="note">Art. 89: a apostila registra a literalidade “Anexo IIII” no texto do artigo, mas o próprio documento apresenta “Anexo III” na sequência.</p>`}
function render(){document.querySelectorAll('.bottom button').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));app.innerHTML=tab==='inicio'?home():tab==='artigos'?articles():tab==='numeros'?numbers():tab==='questoes'?questions():annexes();if(tab==='artigos')renderArticles();scrollTo({top:0,behavior:'instant'})}
function setFilter(x){filter=x;render();}
function toggleDone(n){done.has(n)?done.delete(n):done.add(n);save();renderArticles()}
function toggleFav(n){fav.has(n)?fav.delete(n):fav.add(n);save();renderArticles()}
function answer(btn,n,correct){if(qAnswered.has(n))return;qAnswered.add(n);let chosen=btn.dataset.l;if(chosen===correct)qScore++;document.querySelectorAll(`[data-q="${n}"]`).forEach(x=>{if(x.dataset.l===correct)x.classList.add('correct');else if(x===btn)x.classList.add('wrong');x.disabled=true});document.querySelector('#fb-'+n).classList.add('show');document.querySelector('#score').textContent=`${qScore}/${qAnswered.size}`}
function goArticles(b){filter='bloco '+b;tab='artigos';render()}
document.querySelectorAll('.bottom button').forEach(b=>b.addEventListener('click',()=>{tab=b.dataset.tab;render()}));let fs=16;document.querySelector('#fontBtn').addEventListener('click',()=>{fs=fs===16?18:fs===18?20:16;document.documentElement.style.setProperty('--fs',fs+'px');document.querySelector('#fontBtn').textContent=fs===16?'A+':fs===18?'A++':'A'});render();